// ============================================================ calendario de fiestas: un año religioso condensado
// Los días pares que no tienen otro acontecimiento se celebra una fiesta del ciclo, en su lugar, con un oficiante
// que la explica y un rito en el que el jugador puede participar (la primera opción es la correcta; se barajan).
const FW={f:{female:true,chiton:'#e8dfcc',himation:'#8a3f5e',veil:true,hair:'#3b2a1e'},p:{chiton:'#f3eee2',himation:'#f3eee2',beard:true,hair:'#8d8a85',staff:true},
 r:{toga:true,chiton:'#efe9dc',himation:'#f3eee2',hair:'#5b4532'},rf:{female:true,chiton:'#e2d6c0',himation:'#4a5a6a',veil:true,hair:'#3b2a1e'}};
const FESTS_ATENAS=[
 {id:'panateneas',title:'Panateneas',month:'Hecatombeón (julio)',god:'Atenea',at:'place:partenon',h0:7,h1:18,n:70,
  short:'La procesión del peplo sube a la Acrópolis por el cumpleaños de Atenea.',
  txt:'Es el cumpleaños de Atenea y la gran fiesta de la ciudad. Una procesión sale del Dípilon y cruza el Ágora por la Vía de las Panateneas: sacerdotes, muchachas con cestas, ancianos con ramas de olivo, jóvenes a caballo, metecos con bandejas de ofrendas y un centenar de bueyes para el sacrificio. Llevan a la diosa un peplo nuevo, tejido durante meses por muchachas atenienses. Cada cuatro años se celebran las Grandes Panateneas, con concursos atléticos, musicales y de caballos, y una carrera de antorchas; al vencedor se le dan ánforas llenas de aceite de los olivos sagrados. Este verano tocan las Grandes.',
  off:{name:'Lisímaca',title:'Sacerdotisa ayudante',look:FW.f},
  topics:[['¿Quién teje el peplo?','Las ergastinas, muchachas de buenas familias, y dos niñas pequeñas, las arréforas, que empiezan el trabajo. Se borda con la batalla de los dioses contra los gigantes, en la que Atenea luchó. En las Grandes Panateneas el peplo es enorme y va colgado como la vela de un barco con ruedas.'],['¿Qué se gana en los juegos?','Ánforas pintadas con Atenea armada, llenas de aceite de los olivos sagrados. A un vencedor de la carrera de carros le pueden tocar ciento cuarenta. Muchas se venden luego por toda Grecia: es un premio que también es dinero.']],
  rite:{q:'Te ofrecen llevar una rama de olivo en la procesión. ¿Qué haces?',o:[['Coger la rama y caminar en silencio, detrás de los ancianos','Te colocas en tu sitio. La procesión avanza despacio hacia los Propileos, y por un momento sientes que toda la ciudad camina contigo.'],['Adelantarte para ver mejor el sacrificio','Un heraldo te devuelve a tu sitio. En la procesión, cada uno tiene su lugar.'],['Quedarte mirando desde un pórtico','Desde allí se ve bien, pero no es lo mismo que formar parte de la procesión.']]},
  src:'Friso del Partenón; Aristóteles, Constitución de los atenienses 60; inscripción de premios de las Panateneas (IG II² 2311).'},
 {id:'misterios',title:'Misterios de Eleusis',month:'Boedromión (septiembre)',god:'Deméter y Perséfone',at:'place:eleusinion',h0:6,h1:17,n:60,
  short:'Los iniciados se preparan para la procesión a Eleusis.',
  txt:'Durante nueve días, miles de personas de toda Grecia celebran los Misterios de Deméter y su hija Perséfone. Se reúnen en el Ágora, junto al Eleusinion; al grito de «¡Al mar, iniciados!» se purifican en el mar de Falero con un lechón; y el día grande caminan veinte kilómetros por la Vía Sagrada hasta Eleusis, con la imagen de Yaco y gritos de alegría. Allí, de noche, en la gran sala de los misterios, ven y oyen algo que nunca deben contar. Pueden iniciarse hombres y mujeres, libres y esclavos, si hablan griego y no han derramado sangre.',
  off:{name:'Eumolpo',title:'Sacerdote de la familia de los Eumólpidas',look:FW.p},
  topics:[['¿Qué se ve dentro?','No te lo diré, ni nadie te lo dirá. Revelar los Misterios se castiga con la muerte. Hace treinta años acusaron a Alcibíades de parodiarlos en una fiesta privada, y tuvo que huir. Te diré solo que los iniciados vuelven sin miedo a la muerte.'],['¿Por qué Deméter?','Porque cuando Hades raptó a su hija Perséfone, la diosa vagó por la tierra buscándola y llegó a Eleusis disfrazada de anciana. En su tristeza dejó de crecer el trigo. Desde entonces, Perséfone pasa una parte del año bajo tierra y otra con su madre: por eso hay invierno y primavera.']],
  rite:{q:'Un iniciado te dice que se ha iniciado este año. ¿Qué le preguntas?',o:[['Nada sobre lo que vio: solo cómo se siente','Sonríe agradecido. «Mejor que nunca. Te lo recomiendo». Has respetado el secreto, como hacen todos los griegos.'],['Que te cuente qué hay dentro de la sala','Se aparta, ofendido. «¿Quieres que me condenen? Inícate tú, si quieres saberlo».'],['Que te diga si es todo un engaño','Te mira con lástima y se aleja sin contestar.']]},
  src:'Himno homérico a Deméter; Heródoto VIII 65; Tucídides VI 28 (Alcibíades); Isócrates, Panegírico 28.'},
 {id:'tesmoforias',title:'Tesmoforias',month:'Pianepsión (octubre)',god:'Deméter Tesmófora',at:'place:bema',h0:7,h1:18,n:40,women:true,
  short:'Las mujeres casadas celebran a Deméter en la colina, sin hombres.',
  txt:'Durante tres días, las esposas de los ciudadanos celebran a Deméter en su santuario, cerca de la Pnyx. Los hombres no pueden asistir. El primer día suben y acampan en chozas; el segundo ayunan sentadas en el suelo, en recuerdo del dolor de Deméter; el tercero celebran el «buen nacimiento» con un banquete. Unas mujeres bajan a unas fosas y sacan los restos de lechones que se arrojaron meses antes; se mezclan con las semillas para que la cosecha sea buena. Aristófanes escribió una comedia en la que un pariente de Eurípides se disfraza de mujer para colarse… y lo descubren.',
  off:{name:'Mirrina',title:'Vecina, de camino al santuario',look:FW.f},
  topics:[['¿Por qué solo mujeres?','Porque es la fiesta de la fertilidad de la tierra y de las familias, y Deméter es una madre. Durante esos días nosotras organizamos todo: elegimos a nuestras jefas, gastamos dinero de la fiesta, decidimos. Es el único momento del año en que la ciudad es nuestra.'],['¿Qué hacen los hombres mientras?','Esperar, y aguantarse. Algunos tribunales y el Consejo no se reúnen el día del ayuno. Y los maridos pagan los gastos de su mujer: lo dice la ley.']],
  rite:{q:'El santuario está cerrado a los hombres y a los curiosos. ¿Qué haces?',o:[['Respetar la fiesta y esperar fuera, como hacen todos','Mirrina asiente, satisfecha. «Bien. Te traeré un poco del pastel de sésamo del último día».'],['Disfrazarte para colarte, como en la comedia','Mirrina se ríe a carcajadas. «¡Igual que el pariente de Eurípides! Ya sabes cómo acabó». No te deja ni acercarte.'],['Quejarte de que no es justo','«¿Y que nosotras no votemos sí lo es?», contesta Mirrina, y te deja sin palabras.']]},
  src:'Aristófanes, Las Tesmoforiantes; escolio a Luciano, Diálogos de las heteras 2.1; Iseo III 80.'},
 {id:'pianepsias',title:'Pianepsias',month:'Pianepsión (octubre)',god:'Apolo',at:'place:hefestion',h0:7,h1:17,n:40,
  short:'Puchero de legumbres y ramas de olivo con frutos en las puertas.',
  txt:'Se celebra en recuerdo de la vuelta de Teseo de Creta: cuentan que, al llegar, sus compañeros juntaron lo que les quedaba de provisiones y lo cocieron todo en una sola olla. Por eso hoy se cuece un puchero de habas y legumbres. Los niños llevan la eiresíone, una rama de olivo adornada con lana, higos, panes y pequeños frascos de aceite y miel, y van de casa en casa cantando para pedir buena suerte; luego la cuelgan sobre la puerta, donde se queda todo el año.',
  off:{name:'Calias',title:'Maestro de primeras letras, con sus alumnos',look:{chiton:'#e8e0cf',himation:'#6d7b9a',beard:true,hair:'#5b4532'}},
  topics:[['¿Qué cantan los niños?','Una cancioncilla que pide para la rama higos, pan, miel y aceite, y que la casa tenga de todo. Luego la gente les da algo de comer. Es como pedir el aguinaldo.'],['¿Por qué Teseo?','Porque es el héroe de Atenas: mató al Minotauro y unió las aldeas del Ática en una sola ciudad. Muchas fiestas de este mes recuerdan su regreso.']],
  rite:{q:'Los niños llaman a tu puerta con la rama de olivo y cantan. ¿Qué haces?',o:[['Darles unos higos y dejar que cuelguen la rama en tu puerta','Los niños gritan de alegría. Ya tienes tu eiresíone para todo el año.'],['Cerrar la puerta','Los niños se van decepcionados. Tu puerta se queda sin rama, y sin suerte.'],['Quitarles la rama','Calias te mira escandalizado. Eso es casi un sacrilegio.']]},
  src:'Plutarco, Teseo 22; Aristófanes, Caballeros 729 y Pluto 1054 (la eiresíone).'},
 {id:'apaturias',title:'Apaturias',month:'Pianepsión (octubre)',god:'Zeus Fratrio y Atenea Fratria',at:'place:horos',h0:8,h1:17,n:45,
  short:'Las fratrías inscriben a los niños y los muchachos ofrecen su cabello.',
  txt:'Durante tres días se reúnen las fratrías, las antiguas «hermandades» de familias atenienses. Los padres presentan a sus hijos recién nacidos y juran que son hijos legítimos de madre ateniense; los miembros votan si los aceptan. Hay banquetes y sacrificios. El último día, los muchachos que entran en la edad adulta se cortan el pelo y lo ofrecen a los dioses. Estar inscrito en una fratría es una de las pruebas de que uno es ciudadano.',
  off:{name:'Nicóstrato',title:'Fratriarca, jefe de una fratría',look:{chiton:'#efe6d5',himation:'#8a6a3a',beard:true,hair:'#8d8a85'}},
  topics:[['¿Por qué votan a los niños?','Porque la ciudadanía es un privilegio. Si alguien intentara colar a un hijo de extranjeros, los miembros de la fratría lo rechazarían. Muchos juicios por herencias se resuelven preguntando a la fratría.'],['¿Qué se ofrece?','Por cada niño, el padre ofrece una oveja o una cabra pequeña, y paga un banquete. Los muchachos ofrecen un mechón de pelo, a menudo a Ártemis o a Apolo.']],
  rite:{q:'Un padre presenta a su hijo y pide a los presentes que voten. ¿Qué haces?',o:[['Escuchar los juramentos y respetar el voto de los miembros','Los miembros aceptan al niño y todos brindan. Has visto cómo se hace ciudadano a un ateniense.'],['Votar aunque no seas de la fratría','El fratriarca te detiene: solo votan sus miembros.'],['Burlarte del juramento','Te echan del banquete. Los juramentos ante Zeus no son cosa de risa.']]},
  src:'Iseo VIII 18-20; Demóstenes XLIII 11-15; Heródoto I 147.'},
 {id:'leneas',title:'Leneas',month:'Gamelión (enero)',god:'Dioniso',at:'place:teatro',h0:8,h1:18,n:55,
  short:'El festival de invierno de Dioniso: concurso de comedias.',
  txt:'En pleno invierno, cuando el mar está cerrado a la navegación, Atenas celebra las Leneas en honor de Dioniso. Hay procesión y concursos de comedias y tragedias. Como casi no hay extranjeros en la ciudad, los poetas se atreven a decir cosas más duras sobre la política. Aristófanes ganó aquí con Los acarnienses y Los caballeros.',
  off:{name:'Antífanes',title:'Joven poeta cómico',look:{chiton:'#efe6d5',himation:'#3f6a5a',hair:'#3b2a1e'}},
  topics:[['¿En qué se diferencia de las Dionisias?','En que estamos entre nosotros. En primavera vienen los aliados y los extranjeros, y no conviene lavar los trapos sucios delante de ellos. En invierno, sí. Y aquí los metecos pueden pagar los coros.'],['¿Puedo ganar si escribo una comedia?','Primero tienes que conseguir que el arconte te dé un coro. Luego, que el público no te tire higos. Y luego, que los jueces te voten. Suerte.']],
  rite:{q:'Empieza la comedia y el actor se burla de un político poderoso que está en las gradas. ¿Qué haces?',o:[['Reírte con todos: en las fiestas de Dioniso la comedia puede burlarse de quien sea','Ríes con todo el teatro. El político, de mala gana, también sonríe: en la fiesta del dios no puede hacer otra cosa.'],['Protestar a gritos','Los de tu alrededor te mandan callar. Nadie quiere perderse los chistes.'],['Irte del teatro','Te pierdes la mejor obra del año.']]},
  src:'Aristófanes, Acarnienses 502-508; Aristóteles, Constitución de los atenienses 57.1.'},
 {id:'antesterias',title:'Antesterias',month:'Antesterión (febrero)',god:'Dioniso',at:'place:teatro',h0:9,h1:20,n:55,
  short:'Se abren las tinajas del vino nuevo; concurso de beber y día de los difuntos.',
  txt:'Tres días con tres nombres. El primero, la «apertura de las tinajas»: se prueba el vino nuevo en el santuario de Dioniso de los Pantanos. El segundo, el de las «jarras»: cada uno bebe de su propia jarra, en silencio, en un concurso; a los niños de tres años se les regala una jarrita, y es su primera fiesta de la ciudad. El tercero, el de las «ollas»: se cuecen semillas para Hermes de los muertos, porque esos días las almas de los difuntos vagan por la ciudad. Al final se les despide: «¡Fuera, almas! Se acabaron las Antesterias».',
  off:{name:'Glicera',title:'Nodriza, con un niño de tres años',look:{female:true,chiton:'#d8c9a8',himation:'#6a5a3a',hair:'#3b2a1e'}},
  topics:[['¿Por qué beben en silencio?','Por Orestes: cuando llegó a Atenas manchado por la sangre de su madre, el rey quiso acogerlo sin contaminarse, y mandó que cada uno bebiera de su propia jarra y en silencio. Así se sigue haciendo.'],['¿Y los muertos?','Por la mañana del último día se mastican hojas de espino y se untan las puertas con pez, para que las almas no entren. Por la noche, cuando acaba la fiesta, se les dice que se vayan.']],
  rite:{q:'Al niño de tres años le regalan su primera jarrita y una corona de flores. ¿Qué haces?',o:[['Felicitarle y desearle muchas Antesterias más','La nodriza sonríe. «Es su primera fiesta. Desde hoy ya es un poco ateniense».'],['Beberte el vino de su jarrita','La nodriza te quita la jarrita de las manos, horrorizada. En la suya hay mosto aguado, por suerte.'],['Decir que es una tontería','«Tontería es no tener recuerdos de niño», te dice la nodriza.']]},
  src:'Tucídides II 15.4; Aristófanes, Acarnienses 1000-1234; Eurípides, Ifigenia en Táuride 947-960; Focio, Léxico s.v. thýraze Kêres.'},
 {id:'targelias',title:'Targelias',month:'Targelión (mayo)',god:'Apolo',at:'place:olimpieion',h0:7,h1:17,n:45,
  short:'Cumpleaños de Apolo: primeros frutos y coros de muchachos.',
  txt:'Es el cumpleaños de Apolo. Se ofrece al dios el «targelo», una olla con los primeros frutos de la cosecha cocidos juntos, y coros de muchachos compiten cantando ditirambos. El día antes se purifica la ciudad con un rito muy antiguo: dos personas, elegidas para cargar con las impurezas de todos, son conducidas fuera de la ciudad y expulsadas, golpeadas suavemente con ramas de higuera.',
  off:{name:'Teodoro',title:'Guía de los peregrinos de Apolo',look:FW.p},
  topics:[['¿Qué es un ditirambo?','Un canto en honor de un dios, cantado y bailado por un coro grande, de cincuenta. En las Targelias compiten los muchachos de cada tribu. El que paga el coro vencedor dedica un trípode de bronce, y algunos se ven por la calle de los Trípodes.'],['¿Por qué se expulsa a alguien?','Para que se lleve consigo los males de la ciudad: enfermedades, impurezas, malos presagios. Es un rito muy viejo, y muchos griegos lo encuentran ya extraño.']],
  rite:{q:'Te invitan a ofrecer algo al dios por su cumpleaños. ¿Qué ofreces?',o:[['Un puñado de las primeras frutas del año','El sacerdote lo añade a la olla del targelo. «Apolo agradece lo primero, no lo mejor».'],['Una moneda de plata, para que te favorezca','«El dios no se compra», dice el sacerdote, aunque guarda la moneda en el cepillo.'],['Nada, los dioses no lo necesitan','Los que te rodean te miran con desconfianza. No es buen día para presumir de impiedad.']]},
  src:'Ateneo XIV 656a; Harpocración s.v. pharmakós; Antifonte VI 11 (los coros).'},
 {id:'plinterias',title:'Plinterias',month:'Targelión (mayo)',god:'Atenea Polias',at:'place:polias',h0:6,h1:16,n:30,
  short:'Lavan la imagen de Atenea: día de mal agüero.',
  txt:'Una vez al año, las mujeres de una familia sacerdotal desnudan la antigua imagen de madera de olivo de Atenea, la llevan al mar y lavan sus ropas. Mientras, el templo queda acordonado y la ciudad considera el día nefasto: no se empieza nada importante. Cuando Alcibíades volvió del destierro en el 407, desembarcó precisamente ese día, y muchos lo tomaron como mala señal.',
  off:{name:'Teano',title:'Sacerdotisa de Atenea Polias',look:FW.f},
  topics:[['¿Por qué es mal día?','Porque la diosa está como ausente: su imagen ha salido del templo. Sin su protección, la ciudad está más expuesta. Por eso se espera a que vuelva, limpia y vestida.'],['¿Qué tiene de especial la imagen?','Es la más antigua y sagrada: dicen que cayó del cielo. No es la gran estatua de oro y marfil del Partenón, sino una pequeña figura de madera de olivo, muy vieja, que vestimos y adornamos.']],
  rite:{q:'Un amigo quiere firmar hoy un contrato importante. ¿Qué le aconsejas?',o:[['Que espere a mañana: hoy es día de Plinterias','Tu amigo asiente. «Tienes razón, nadie empieza nada hoy». Teano lo aprueba con la cabeza.'],['Que lo firme hoy, que no pasa nada','Tu amigo duda. Los que os rodean os miran como a dos imprudentes.'],['Que lo firme en el templo','El templo está cerrado y acordonado. Ni hablar.']]},
  src:'Plutarco, Alcibíades 34; Jenofonte, Helénicas I 4.12; Focio s.v. Kallyntéria kaì Plyntéria.'},
 {id:'bufonias',title:'Bufonias',month:'Esciroforión (junio)',god:'Zeus Polieo',at:'place:partenon',h0:8,h1:15,n:40,
  short:'El sacrificio del buey, y el juicio extrañísimo que lo sigue.',
  txt:'En el altar de Zeus Polieo, en la Acrópolis, se dejan granos de cebada y trigo. Unos bueyes dan vueltas alrededor, y el que come primero es sacrificado. El que lo mata arroja el hacha y huye como si fuera culpable. Después se celebra un juicio en el Pritaneo: los que trajeron el agua culpan a los que afilaron el hacha, estos a los que la entregaron, y así hasta que la culpa recae en el cuchillo, que es condenado y arrojado al mar. Luego se rellena la piel del buey con paja y se le uncen a un arado, como si resucitara.',
  off:{name:'Carión',title:'Carnicero de sacrificios',look:{exomis:true,chiton:'#a89070',beard:true,hair:'#3b2a1e'}},
  topics:[['¿Por qué juzgan al cuchillo?','Porque matar a un buey de labranza, el compañero del campesino, era antiguamente un delito. El rito recuerda esa culpa: alguien tiene que cargar con ella, y nadie quiere. Al final, la culpa es del cuchillo.'],['¿Siempre se sacrifican animales?','En las grandes fiestas, sí: bueyes, ovejas, cabras, cerdos. La carne se reparte entre la gente: para muchos pobres, es la única carne que comen en meses. A los dioses se les quema la grasa y los huesos.']],
  rite:{q:'En el juicio te preguntan a quién culpas de la muerte del buey. ¿Qué respondes?',o:[['Al cuchillo, como manda la tradición','Todos asienten muy serios y el cuchillo es condenado al mar. Has participado en uno de los ritos más antiguos de Atenas.'],['Al que lo mató','El sacerdote frunce el ceño: el que lo mató ya huyó, y no es eso lo que se pregunta.'],['A nadie, es solo un buey','Te miran como a un forastero que no entiende nada.']]},
  src:'Pausanias I 24.4 y I 28.10; Porfirio, Sobre la abstinencia II 29-30; Aristófanes, Nubes 985.'},
 {id:'arreforias',title:'Arreforias',month:'Esciroforión (junio)',god:'Atenea',at:'place:erecteion',h0:19,h1:23,n:20,
  short:'De noche, dos niñas bajan de la Acrópolis con cestas secretas.',
  txt:'Dos niñas de entre siete y once años, las arréforas, viven durante un tiempo en la Acrópolis, juegan a la pelota en un patio propio y ayudan a empezar el peplo de Atenea. Una noche al año, la sacerdotisa les pone sobre la cabeza unas cestas tapadas, sin que ni ella ni las niñas sepan qué llevan. Bajan por un pasadizo hasta un santuario de Afrodita, dejan allí las cestas y vuelven con otro objeto también tapado. Luego otras niñas ocupan su lugar.',
  off:{name:'Teano',title:'Sacerdotisa de Atenea Polias',look:FW.f},
  topics:[['¿Qué llevan en las cestas?','Nadie lo sabe, ni siquiera ellas. Algunos dicen que el rito recuerda a las hijas de Cécrope, que abrieron una cesta que Atenea les había prohibido abrir, y vieron dentro al niño Erictonio con forma de serpiente.'],['¿Quién las elige?','El arconte rey, entre las hijas de buenas familias. Es un gran honor. En las estatuas de la Acrópolis verás nombres de niñas que fueron arréforas.']],
  rite:{q:'Las niñas pasan a tu lado con las cestas tapadas. ¿Qué haces?',o:[['Apartarte en silencio y no mirar','Las niñas pasan. Nadie ha visto nada, como debe ser.'],['Preguntarles qué llevan','Las niñas no contestan: no lo saben. La sacerdotisa te aparta con un gesto.'],['Seguirlas para ver adónde van','Un guardia te cierra el paso. Hay cosas que no se siguen.']]},
  src:'Pausanias I 27.3; Harpocración s.v. arrephoreîn.'},
 {id:'adonias',title:'Adonias',month:'Verano',god:'Adonis y Afrodita',at:'place:dipilon',h0:9,h1:20,n:35,
  short:'Las mujeres suben a los tejados los «jardines de Adonis» y lloran al joven muerto.',
  txt:'Una fiesta privada, de mujeres, que no organiza la ciudad. Unos días antes siembran en macetas y trozos de ánfora semillas que crecen muy deprisa: trigo, lechuga, hinojo. Son los «jardines de Adonis», el joven amado por Afrodita que murió en una cacería. En la fiesta los suben a los tejados, donde se secan enseguida al sol, y lloran a Adonis con cantos de lamento. La planta que crece rápido y muere rápido es como su vida.',
  off:{name:'Filina',title:'Música de banquetes',look:{female:true,chiton:'#e8b84a',himation:'#a8392b',hair:'#3b2a1e'}},
  topics:[['¿De dónde viene Adonis?','De Oriente, de Chipre y de Fenicia. Es un culto que llegó con los comerciantes y que las atenienses han hecho suyo. Afrodita lo amaba, y cuando murió, de su sangre nacieron las anémonas.'],['¿Por qué en los tejados?','Porque es lo más alto de la casa, cerca del cielo, y porque es nuestro: los hombres no suben. Desde allí se oyen los cantos de una casa a otra. Una vez, durante una Asamblea importante, se oían por toda la ciudad.']],
  rite:{q:'Una vecina te ofrece una maceta con brotes para subir al tejado. ¿Qué haces?',o:[['Ayudarla a subirla y escuchar sus cantos con respeto','Ella te da las gracias. Desde el tejado se ve media ciudad llena de macetas verdes.'],['Decir que es una fiesta extranjera y ridícula','La vecina te da la espalda. También los dioses de fuera tienen sus fieles.'],['Regar la maceta para que no se seque','«Tiene que secarse», te explica. «Así es la vida de Adonis».']]},
  src:'Aristófanes, Lisístrata 387-398; Platón, Fedro 276b; Plutarco, Nicias 13.'},
 {id:'braurionias',title:'Braurionias',month:'Cada cuatro años, en primavera',god:'Ártemis Braurónia',at:'place:brauronion',h0:8,h1:17,n:35,
  short:'Las niñas que han servido a Ártemis como «osas» terminan su servicio.',
  txt:'En el santuario de Ártemis en Braurón, en la costa del Ática, y en su recinto de la Acrópolis, las niñas atenienses pasan un tiempo sirviendo a la diosa antes de ser mayores. Las llaman «osas»: llevan túnicas de color azafrán, corren carreras y bailan. Cuentan que una osa domesticada vivía en el santuario y que unos muchachos la mataron; la diosa se enfadó, y desde entonces las niñas «hacen de osas» para aplacarla.',
  off:{name:'Hegeso',title:'Iniciada, que fue «osa» de niña',look:FW.f},
  topics:[['¿Qué hacíais allí?','Correr, bailar, aprender himnos, cuidar del santuario. Era como una escuela de la diosa. Aristófanes hace decir a un coro de mujeres que de niñas fueron osas en Braurón.'],['¿Y qué se ofrece a Ártemis?','Las mujeres que han dado a luz le ofrecen ropas. En Braurón se guardan montones de vestidos, con los nombres de las mujeres apuntados en listas.']],
  rite:{q:'Las niñas corren una carrera en honor de Ártemis. ¿Qué haces?',o:[['Animarlas y aplaudir a todas al llegar','Las niñas se ríen al pasar. La sacerdotisa sonríe: la diosa quiere a sus osas alegres.'],['Apostar por una','La sacerdotisa te mira con desaprobación. No es una carrera de caballos.'],['Preguntar por qué no corren los niños','«Ellos tienen sus fiestas, y esta es nuestra», te responde Hegeso.']]},
  src:'Aristófanes, Lisístrata 641-647; Eurípides, Ifigenia en Táuride 1462-1467; inventarios de Braurón (IG II² 1514-1531).'}
];
const FESTS_ROMA=[
 {id:'saturnales',title:'Saturnales',month:'17 de diciembre y días siguientes',god:'Saturno',at:'place:ro_saturno',h0:8,h1:22,n:70,
  short:'El mundo al revés: los esclavos son servidos y todos se hacen regalos.',
  txt:'La fiesta más alegre del año. Tras un sacrificio en el templo de Saturno y un banquete público, se grita «¡Io, Saturnalia!». Durante unos días se cierran los tribunales y las escuelas, se dejan las togas y se lleva una túnica cómoda y el gorro de los libertos. Se permite jugar a los dados en público, se eligen reyes de broma y, en muchas casas, los amos sirven la mesa a sus esclavos. La gente se regala velas y figuritas de barro, que se venden en un mercado especial.',
  off:{name:'Hermeros',title:'Liberto enriquecido',look:{chiton:'#e8b84a',himation:'#7a2a1e',hair:'#3b2a1e'}},
  topics:[['¿Por qué los amos sirven a los esclavos?','Por la edad de oro de Saturno, cuando no había esclavos ni amos. Unos días al año jugamos a que vuelve. Yo fui esclavo: te aseguro que una cena no compensa un año, pero ayuda.'],['¿Qué se regala?','Velas de cera, para la luz de los días más cortos, y figuritas de barro, los sigillaria. Los ricos regalan más: vajillas, ropa… y los poetas escriben versos para acompañar los regalos.']],
  rite:{q:'En la casa donde te alojas, los esclavos se sientan a la mesa. ¿Qué haces?',o:[['Servirles la comida, como manda la fiesta','Los esclavos se ríen y brindan por ti. «¡Io, Saturnalia!». Por un día, la casa es de todos.'],['Sentarte a comer con los amos, como siempre','Te miran raro. En Saturnales, eso es no entender nada.'],['Irte a tu cuarto','Te pierdes la cena más divertida del año.']]},
  src:'Macrobio, Saturnales I 7 y I 24; Séneca, Cartas 18; Catulo 14.15.'},
 {id:'lupercales',title:'Lupercales',month:'15 de febrero',god:'Fauno',at:'place:ro_lupercal',h0:8,h1:15,n:60,
  short:'Los lupercos corren alrededor del Palatino con tiras de piel de cabra.',
  txt:'Junto a la cueva del Lupercal, donde la loba amamantó a Rómulo y Remo, los sacerdotes lupercos sacrifican cabras. A dos jóvenes les tocan la frente con el cuchillo ensangrentado, se la limpian con lana mojada en leche, y ellos deben reír. Después, los lupercos, casi desnudos, corren alrededor del Palatino golpeando con tiras de piel de cabra, las februa, a quien encuentran: es un rito de purificación del que viene el nombre del mes de febrero.',
  off:{name:'Gneo Domicio Calvino',title:'Augur',look:FW.r},
  topics:[['¿Por qué deben reír los jóvenes?','Nadie lo sabe con certeza. Quizá para mostrar que el rito no los mancha, que salen limpios y vivos. Muchos ritos son más viejos que sus explicaciones.'],['¿Por qué se llama febrero?','Por las februa, los instrumentos de purificación: las tiras de piel, la lana, la sal. Febrero es el mes de las purificaciones, el último del año antiguo.']],
  rite:{q:'Los lupercos pasan corriendo junto a ti. ¿Qué haces?',o:[['Quedarte en tu sitio y dejarte tocar por las tiras: trae purificación y buena suerte','Una tira de piel te roza el brazo. La gente aplaude: estás purificado para el nuevo año.'],['Echar a correr para esquivarlos','Los lupercos se ríen y te persiguen un poco. No es más que un juego… pero te has perdido la purificación.'],['Gritarles que es una barbaridad','El augur te mira con frialdad. Es uno de los ritos más antiguos de Roma.']]},
  src:'Ovidio, Fastos II 267-452; Plutarco, Rómulo 21; Dionisio de Halicarnaso I 80.'},
 {id:'parilias',title:'Parilias',month:'21 de abril',god:'Pales',at:'place:ro_palatino',h0:17,h1:23,n:60,
  short:'El cumpleaños de Roma: saltar hogueras de paja para purificarse.',
  txt:'Es la fiesta de Pales, diosa de los pastores, y el día en que Rómulo fundó Roma. Al amanecer se barren los establos, se adornan con ramas y se purifica a las ovejas con humo de azufre. Las vestales reparten un polvo de purificación hecho con ceniza de terneros, sangre de caballo y tallos de habas. Por la noche se encienden hogueras de paja, y jóvenes y mayores saltan por encima de ellas tres veces.',
  off:{name:'Gavio',title:'Pastor trashumante',look:{short:true,noHimation:true,chiton:'#8a7350',beard:true,hair:'#3b2a1e',staff:true}},
  topics:[['¿Por qué se salta el fuego?','Porque el fuego purifica: limpia a las personas y al ganado de todo lo malo del año. Saltar tres veces es lo correcto, y sin quemarse la túnica, a ser posible.'],['¿Cuántos años cumple Roma?','Según el cálculo de Varrón, Rómulo la fundó hace ochocientos treinta y tres años. Algunos dicen que hace algo menos. Un pastor fundó Roma; por eso es también nuestra fiesta.']],
  rite:{q:'Te toca saltar la hoguera de paja. ¿Cuántas veces saltas?',o:[['Tres veces, como manda la tradición','Saltas tres veces entre aplausos. Hueles a humo, pero estás purificado.'],['Una vez y ya está','«¡Tres!», te gritan los pastores. Con una no vale.'],['Ninguna: es peligroso','Los niños se ríen de ti. Es una hoguera de paja: arde poco.']]},
  src:'Ovidio, Fastos IV 721-862; Propercio IV 4.73-78; Varrón, De re rustica II 1.9.'},
 {id:'vestalia',title:'Vestalia',month:'7 al 15 de junio',god:'Vesta',at:'place:ro_vesta',h0:7,h1:17,n:55,
  short:'Las matronas entran descalzas al santuario de Vesta. Fiesta de panaderos.',
  txt:'Durante unos días se abre la despensa sagrada del templo de Vesta, que el resto del año solo ven las vestales. Las matronas romanas entran descalzas a llevar ofrendas de comida. Es también la fiesta de los panaderos y molineros: los asnos que mueven las piedras de molino descansan, adornados con coronas de flores y panecillos colgados del cuello. El último día se barre el templo y la basura se tira al Tíber; desde entonces ya se pueden hacer negocios.',
  off:{name:'Cornelia',title:'Virgen vestal',look:{female:true,chiton:'#f3eee2',himation:'#f3eee2',veil:true,hair:'#5b4532'}},
  topics:[['¿Qué hay en la despensa sagrada?','Objetos que garantizan la permanencia de Roma. No puedo decirte más. Dicen que entre ellos está el Paladio, la imagen de Palas que Eneas trajo de Troya.'],['¿Por qué los asnos llevan coronas?','Porque Vesta es la diosa del hogar y del fuego, y el pan sale del horno y del molino. Ovidio cuenta que un asno, con su rebuzno, salvó a Vesta de un mal encuentro. Así que, al menos un día al año, los asnos descansan.']],
  rite:{q:'Una matrona va a entrar en el santuario con su ofrenda. ¿Qué haces tú?',o:[['Esperar fuera: solo entran las mujeres, descalzas','Cornelia asiente. Desde fuera ves pasar a las matronas con sus cestas en silencio.'],['Entrar con ella','Una vestal te cierra el paso con firmeza. Ese lugar no es para ti.'],['Quitarte las sandalias y entrar detrás','«Descalzo o no, no puedes entrar», te dice Cornelia, con paciencia.']]},
  src:'Ovidio, Fastos VI 249-468; Festo s.v. Quando stercus delatum fas; Propercio IV 1.21.'},
 {id:'matronalia',title:'Matronalia',month:'1 de marzo',god:'Juno Lucina',at:'place:ro_subura',h0:8,h1:18,n:45,
  short:'Fiesta de las madres: regalos a las esposas, y las señoras sirven a sus esclavas.',
  txt:'El primer día de marzo, el antiguo comienzo del año, las matronas suben al templo de Juno Lucina, protectora de los partos, en el Esquilino, con el pelo suelto y sin cinturón, para que los partos no tengan nudos. Ese día los maridos rezan por sus esposas y les hacen regalos, y las señoras de la casa sirven la comida a sus esclavas, como los amos hacen en Saturnales.',
  off:{name:'Sulpicia',title:'Poetisa',look:FW.rf},
  topics:[['¿Por qué el pelo suelto?','Porque en los ritos de los partos no debe haber nada atado ni anudado: ni cinturones ni trenzas. Es una forma de pedir a Juno que el niño nazca sin obstáculos.'],['¿Qué se regala?','Flores, joyas, dinero para la casa. Y versos, si el marido es poeta. Los míos no los compro: los escribo.']],
  rite:{q:'Es 1 de marzo y estás en casa de una familia romana. ¿Qué haces?',o:[['Felicitar a la señora de la casa y llevarle unas flores','La matrona sonríe y te da las gracias. Hoy es su día.'],['Pedir que te sirvan la comida','Hoy las señoras sirven a las esclavas, no a los invitados. Te toca esperar.'],['Felicitar solo al marido','Te miran raro. La fiesta es de ella.']]},
  src:'Ovidio, Fastos III 167-258; Macrobio, Saturnales I 12.7; Marcial V 84.'},
 {id:'liberalia',title:'Liberalia',month:'17 de marzo',god:'Líber',at:'place:ro_rostra',h0:8,h1:17,n:55,
  short:'Los muchachos visten por primera vez la toga de hombre.',
  txt:'Es la fiesta de Líber, el dios del vino y de la libertad. Unas ancianas coronadas de hiedra venden por las calles tortas de miel, y ofrecen un trocito al dios en un pequeño altar portátil. Es el día preferido para que los muchachos de unos quince o dieciséis años dejen la toga infantil con borde púrpura y el amuleto que llevaban al cuello, y se vistan por primera vez la toga blanca de hombre. Su familia y sus amigos los acompañan al Foro y al Capitolio. Desde hoy son ciudadanos adultos.',
  off:{name:'Lucio Fabio',title:'Padre orgulloso, en la salutatio',look:FW.r},
  topics:[['¿Qué es la bulla?','El amuleto de oro o de cuero que los niños libres llevan al cuello desde que nacen, para protegerlos. Al ponerse la toga de hombre, se dedica a los Lares de la casa.'],['¿Por qué el Foro?','Porque es la vida pública: ahí se vota, se juzga, se habla. Un ciudadano adulto entra en el Foro por primera vez acompañado de los suyos. Luego se inscribe en las listas de su tribu.']],
  rite:{q:'Un muchacho del barrio estrena su toga y va al Foro con su familia. ¿Qué haces?',o:[['Unirte al cortejo y felicitarle por su nueva toga','La familia te recibe con alegría. Cuantos más acompañan, más honor para el muchacho.'],['Reírte de lo mal que se ha puesto la toga','Es verdad que le cuelga torcida, pero hoy no es el día para decírselo.'],['Seguir tu camino','Te pierdes uno de los momentos más importantes en la vida de un romano.']]},
  src:'Ovidio, Fastos III 713-790; Cicerón, Cartas a Ático VI 1.12; Persio V 30-31.'},
 {id:'floralia',title:'Floralia',month:'28 de abril al 3 de mayo',god:'Flora',at:'place:ro_circo',h0:9,h1:19,n:70,
  short:'Flores, ropa de colores, mimos y legumbres lanzadas a la gente.',
  txt:'Seis días de fiesta para Flora, diosa de las flores y de la primavera. La gente se viste con ropas de colores (en las demás fiestas se va de blanco), se adorna con coronas de flores y llena los teatros para ver mimos y farsas. En el Circo se sueltan liebres y cabras, animales inofensivos, y se lanzan a la multitud garbanzos, habas y altramuces, señal de abundancia.',
  off:{name:'Ambivio',title:'Jefe de una compañía de cómicos',look:{chiton:'#c96a2a',himation:'#3f6a5a',hair:'#3b2a1e'}},
  topics:[['¿Por qué colores?','Porque Flora es la diosa de lo que florece, y la primavera no es blanca. Ovidio se lo preguntó a la propia diosa en un poema, y ella le dijo: porque la tierra se viste de colores en esta época.'],['¿Y las liebres?','Porque Flora no protege los bosques ni a las fieras, sino los jardines y los campos. Así que en su fiesta se sueltan animales pacíficos, no leones.']],
  rite:{q:'Desde las gradas lanzan legumbres a la multitud. ¿Qué haces?',o:[['Coger un puñado de altramuces y compartirlos con tus vecinos de asiento','Te sonríen y te ofrecen a cambio un trago de su vino aguado. La fiesta es compartir.'],['Pelearte por coger más que nadie','Acabas con un codazo y sin altramuces.'],['Quejarte de que te han dado en la cabeza','Los de al lado se ríen. En Floralia, eso es buena suerte.']]},
  src:'Ovidio, Fastos V 183-378; Persio V 177-179; Plinio, Historia natural XVIII 286.'},
 {id:'lemurias',title:'Lemurias',month:'9, 11 y 13 de mayo',god:'Los difuntos (lémures)',at:'place:ro_insulae',h0:21,h1:24,n:20,
  short:'A medianoche, el padre de familia echa habas negras a los espíritus.',
  txt:'Tres noches de mayo en las que las almas inquietas de los muertos, los lémures, vagan por las casas. A medianoche, el padre de familia se levanta descalzo, hace chasquear los dedos para alejar a los espíritus, se lava las manos en agua de fuente y, sin mirar atrás, echa habas negras por encima del hombro mientras repite nueve veces: «Con estas habas me rescato a mí y a los míos». Después golpea un objeto de bronce y pide a los espíritus que se vayan.',
  off:{name:'Tito Verrio',title:'Gramático y maestro',look:FW.r},
  topics:[['¿Por qué habas?','Las habas se relacionan con los muertos en muchos ritos antiguos. Pitágoras ya prohibía comerlas. Dicen que los espíritus las recogen y se marchan contentos.'],['¿Es lo mismo que la fiesta de los difuntos de febrero?','No. En febrero, en las Parentalia, se honra con cariño a los antepasados en sus tumbas. Las Lemurias son para los espíritus sin descanso, a los que se teme. Por eso mayo es mal mes para casarse.']],
  rite:{q:'Es medianoche y el padre de familia te ofrece hacer el rito con él. ¿Qué haces al echar las habas?',o:[['No mirar atrás, como manda el rito','El padre asiente. Se golpea el bronce y la casa queda en paz hasta el año que viene.'],['Mirar atrás para ver si hay algo','El padre se pone pálido. Habrá que repetirlo todo.'],['Comerte las habas','El padre te arrebata el puñado. ¡Son para los muertos!']]},
  src:'Ovidio, Fastos V 419-492.'},
 {id:'compitalia',title:'Compitalia',month:'Principios de enero',god:'Lares de las encrucijadas',at:'place:ro_compitum',h0:8,h1:18,n:50,
  short:'En cada cruce de calles se honra a los Lares; muñecos de lana en las puertas.',
  txt:'En cada encrucijada de Roma hay un pequeño santuario de los Lares del barrio. En las Compitalia se adorna, se sacrifica y se celebra una fiesta del vecindario, organizada por los magistrados de cada barrio, muchas veces libertos. La noche antes, en las puertas de las casas se cuelgan muñecos de lana, uno por cada persona libre, y bolas de lana por cada esclavo, para que los espíritus se lleven los muñecos en lugar de a las personas.',
  off:{name:'Aulo Sempronio',title:'Vigil del barrio',look:{short:true,noHimation:true,chiton:'#8a3a2a',beard:true,hair:'#2b1f17'}},
  topics:[['¿Quiénes son los Lares?','Los protectores de la casa y del barrio. Cada casa tiene su larario, un pequeño altar donde se les ofrece algo cada día. Augusto mandó añadir en los santuarios de los cruces su propio Genio, y desde entonces hay unos doscientos sesenta en Roma.'],['¿Quién organiza la fiesta?','Los vicomagistri, cuatro por barrio, elegidos entre los vecinos. Muchos son libertos: es uno de los pocos honores públicos que pueden tener. Visten toga con borde púrpura ese día, y van muy orgullosos.']],
  rite:{q:'Tus vecinos cuelgan muñecos de lana en la puerta. ¿Qué haces?',o:[['Colgar uno por ti, como los demás vecinos','Los vecinos te sonríen. Ya eres del barrio.'],['Decir que es una superstición','Una anciana te mira con lástima. «Ya lo dirás cuando vengan los espíritus».'],['Llevarte un muñeco de recuerdo','El vigil te lo quita con cara de pocos amigos.']]},
  src:'Macrobio, Saturnales I 7.34-35; Festo s.v. pilae; Suetonio, Augusto 30-31.'},
 {id:'ludiromani',title:'Juegos Romanos y banquete de Júpiter',month:'4 al 19 de septiembre',god:'Júpiter Óptimo Máximo',at:'place:ro_jupiter',h0:8,h1:19,n:60,
  short:'Procesión al Circo y banquete de los dioses en el Capitolio.',
  txt:'Los juegos más antiguos de Roma, en honor de Júpiter. Empiezan con una gran procesión desde el Capitolio hasta el Circo Máximo: jóvenes a caballo, aurigas, bailarines con armas, músicos y, al final, las imágenes de los dioses en andas. El día 13 se celebra el banquete de Júpiter: las imágenes de Júpiter, Juno y Minerva se recuestan en lechos ante una mesa servida, y los senadores comen con ellos en el Capitolio. Este año el templo de Júpiter ha ardido en el incendio y habrá que reconstruirlo.',
  off:{name:'Gneo Domicio Calvino',title:'Augur',look:FW.r},
  topics:[['¿Qué pasa si algo sale mal en la procesión?','Si un caballo tropieza, si un flautista se calla o si alguien suelta las riendas, hay que repetir los juegos desde el principio. Es la instauratio. Los dioses quieren que el rito se haga perfecto.'],['¿Cómo comen los dioses?','Sus imágenes se colocan reclinadas en lechos, como en un banquete romano, con la comida delante. Lo llamamos lectisternio. Luego los magistrados comen la comida en su nombre.']],
  rite:{q:'En la procesión, el flautista se para un momento. ¿Qué ocurre?',o:[['Hay que repetir la procesión: el rito debe hacerse sin fallos','El augur asiente. «Exacto. Con los dioses, la exactitud es respeto». Todo vuelve a empezar.'],['Nada, se sigue adelante','El augur te mira escandalizado. Un rito mal hecho no vale.'],['Se castiga al flautista con la muerte','«No exageres», dice el augur. «Basta con repetirlo».']]},
  src:'Dionisio de Halicarnaso VII 72; Livio V 52 y XXV 2; Dion Casio LXVI 24 (el incendio del 80).'},
 {id:'isia',title:'Navigium Isidis',month:'5 de marzo',god:'Isis',at:'place:ro_iseo',h0:8,h1:17,n:55,
  short:'Procesión de Isis para abrir la temporada de navegación.',
  txt:'Al terminar el invierno, Isis, protectora de los navegantes, abre el mar. Una procesión sale de su templo: personas disfrazadas de soldados, cazadores, filósofos o pescadores; mujeres de blanco que esparcen flores; músicos con sistros, unos sonajeros de bronce; y los sacerdotes con la cabeza rapada llevando objetos sagrados. En el puerto se bota un barco nuevo, cargado de ofrendas, y se le deja ir mar adentro.',
  off:{name:'Sarapión',title:'Sacerdote de Isis',look:{chiton:'#f3eee2',himation:'#f3eee2',hair:'#2b1f17'}},
  topics:[['¿Por qué Isis protege a los marineros?','Porque buscó por todo el mar los pedazos del cuerpo de su esposo Osiris, y lo devolvió a la vida. Es la señora del mar y de los vientos. Los marineros de Alejandría la trajeron a todos los puertos del Mediterráneo.'],['¿Puede cualquiera seguir a Isis?','Cualquiera: hombres y mujeres, libres y esclavos, romanos y extranjeros. Para ser iniciado hay que ayunar, purificarse y esperar a que la diosa te llame en un sueño.']],
  rite:{q:'La procesión pasa y una mujer de blanco te ofrece flores. ¿Qué haces?',o:[['Coger una flor y esparcir los pétalos al paso de la procesión, como los demás','Sarapión agita el sistro en señal de bendición. Que Isis te guarde en tus viajes.'],['Rechazarlas: no es una diosa romana','La mujer sigue su camino. Muchos romanos, y hasta el emperador, honran ya a Isis.'],['Pedir dinero a cambio','Te miran como a un loco.']]},
  src:'Apuleyo, Metamorfosis XI 7-17; Plutarco, Isis y Osiris; Juvenal VI 526-541.'},
 {id:'mercuralia',title:'Mercuralia',month:'15 de mayo',god:'Mercurio',at:'place:ro_capena',h0:7,h1:16,n:40,
  short:'Los comerciantes se rocían con agua sagrada para que les perdonen sus mentiras.',
  txt:'Es la fiesta de Mercurio, dios del comercio y de los mensajeros, que tiene su templo junto al Circo Máximo. Los comerciantes van a una fuente cerca de la Puerta Capena, mojan una rama de laurel en su agua y se rocían a sí mismos y a sus mercancías. Ovidio cuenta, con humor, que le piden al dios que les perdone las mentiras del año pasado y les permita seguir ganando con las del año que viene.',
  off:{name:'Tiberio Claudio Eutiques',title:'Comerciante de grano',look:{chiton:'#d8c9a8',himation:'#4f6a7d',beard:true,hair:'#5b4532'}},
  topics:[['¿Por qué Mercurio?','Porque es el dios de los que se mueven: viajeros, mensajeros, comerciantes… y ladrones. Es listo y rápido. Su nombre viene de merx, mercancía.'],['¿De verdad pedís perdón por mentir?','Eso dice el poeta, y algo de verdad tiene. Pero yo pido sobre todo que no se me hunda ningún barco este año.']],
  rite:{q:'Un comerciante te ofrece la rama de laurel mojada. ¿Qué haces?',o:[['Rociarte con el agua y desear buenos negocios a todos','Eutiques se ríe. «Ahora ya puedes vender lo que quieras… con moderación».'],['Rociarle a él, por lo que pueda haber mentido','El comerciante se ríe a carcajadas. «Tienes razón, lo necesito más que tú».'],['Decir que tú nunca mientes','Todos se ríen. «Por eso mismo, rocíate dos veces».']]},
  src:'Ovidio, Fastos V 663-692; Livio II 21 y 27 (el templo de Mercurio).'},
 {id:'octubre',title:'Caballo de Octubre',month:'15 de octubre',god:'Marte',at:'place:ro_panteon',h0:9,h1:16,n:60,
  short:'Carrera de carros en el Campo de Marte y lucha de dos barrios por un trofeo.',
  txt:'Al final de la temporada de guerra, se corre en el Campo de Marte una carrera de carros de dos caballos. El caballo de la derecha del carro vencedor se sacrifica a Marte. Los vecinos de dos barrios, la Vía Sacra y la Subura, se pelean por quedarse con la cabeza del caballo, que adorna con panes: si ganan los de la Subura, la cuelgan en una torre de su barrio. La cola se lleva corriendo a la Regia, en el Foro, y su sangre se guarda para el rito de purificación de las Parilias.',
  off:{name:'Félix',title:'Auriga de los Verdes',look:{short:true,noHimation:true,chiton:'#3a7a3a',hair:'#3b2a1e'}},
  topics:[['¿Por qué un caballo?','Porque es el animal de la guerra y de Marte, y el año de las campañas termina en octubre. Es un rito muy antiguo, de cuando Roma era un pueblo de soldados campesinos.'],['¿Quién gana la pelea?','Depende del año. Hay que ver a los de la Subura: llevan meses entrenando. Los de la Vía Sacra son más finos… pero no menos testarudos.']],
  rite:{q:'Los de la Subura te piden que ayudes a su barrio en la pelea por la cabeza del caballo. ¿Qué haces?',o:[['Animar desde fuera, sin meterte en la pelea','Desde el borde ves la pelea. La gente grita, empuja y se ríe: es un rito, pero también una fiesta de barrio.'],['Meterte a empujar con ellos','Acabas con la túnica rota y un ojo morado. Al menos eres ya un poco de la Subura.'],['Avisar a los vigiles para que lo prohíban','El vigil se ríe. «¿Prohibir el Caballo de Octubre? Hace siglos que se hace».']]},
  src:'Festo s.v. October equus; Plutarco, Cuestiones romanas 97; Polibio XII 4b.'}
];
const FESTS=()=>MODE==='roma'?FESTS_ROMA:FESTS_ATENAS;
// los días pares sin otro acontecimiento: la siguiente fiesta del ciclo
function festOfDay(d){const L=FESTS();if(d<2||d%2)return null;return L[(d/2-1)%L.length];}
function festNextDay(f){const L=FESTS(),i=L.indexOf(f),d=state.day||1;let k=2*(i+1);while(k<d)k+=2*L.length;return k;}
function festEvent(f){return{id:'f_'+f.id,title:f.title,short:f.short,h0:f.h0,h1:f.h1,n:f.n||40,r:f.r||22,at:()=>stAnchor(f.at),txt:f.txt+' <i>(Se celebra en '+f.month+'.)</i>',fest:f};}
const FEST_ACT={o:null};
function festSpawn(ev,p,g){FEST_ACT.o=null;const f=ev.fest;if(!f)return;const q=findFree(p.x+4,p.z+4,0.6);
  const w=new THREE.Group();w.position.set(q[0],floorAt(q[0],q[1]),q[1]);scene.add(w);const om=makePerson(Object.assign({noVary:true},f.off.look));w.add(om);
  const lb=labelSprite(f.off.name,f.off.title,true);lb.position.y=2.45;lb.visible=false;om.add(lb);const mk=markerSprite();mk.position.y=2.95;mk.visible=!(state.fest||{})[f.id];om.add(mk);
  g.userData.off=w;FEST_ACT.o={kind:'fest',x:q[0],z:q[1],g:w,lb,mk,data:{name:f.off.name,role:f.off.title},f};}
function festDialog(f){dlg={n:null};ui='dialog';releasePointer();const done=(state.fest||{})[f.id];
  $('dGlyph').textContent='✦';setName(f.off.name,true);$('dTitle').textContent=f.off.title+' · '+f.title;
  const head='<p class="sub">'+f.title+' · '+f.god+' · '+f.month+'</p>';
  const menu=()=>{const o=$('dOpts');o.innerHTML='';let k=1;const add=(t,fn,c)=>{const b=document.createElement('button');if(c)b.className=c;b.innerHTML='<span class="n">'+(k++)+'</span><span>'+t+'</span>';b.onclick=fn;o.appendChild(b);};
    add('¿Qué se celebra hoy?',()=>{$('dBody').innerHTML=head+'<p>'+f.txt+'</p>';menu();});
    f.topics.forEach(t=>add(t[0],()=>{$('dBody').innerHTML=head+'<p>'+t[1]+'</p>';menu();}));
    if(!(state.fest||{})[f.id])add('Participar en el rito',()=>rite(),'quiz');
    add('Despedirse',closeDialog);setTimeout(()=>{const b=o.querySelector('button');b&&b.focus({preventScroll:true});},30);};
  const rite=()=>{const R0=f.rite,o=$('dOpts');$('dBody').innerHTML=head+'<p><b>'+R0.q+'</b></p>';o.innerHTML='';
    R0.o.map((x,i)=>[x,i===0]).sort(()=>R()-0.5).forEach(([x,good],i)=>{const b=document.createElement('button');b.className='quiz';b.innerHTML='<span class="n">'+(i+1)+'</span><span>'+x[0]+'</span>';
      b.onclick=()=>{let msg='<p>'+x[1]+'</p>';if(good){if(!state.fest)state.fest={};state.fest[f.id]=1;state.obols+=2;qAdd('eu',3,'Has participado como es debido en una fiesta.');qAdd('kl',1);sfxCoin();if(FEST_ACT.o)FEST_ACT.o.mk.visible=false;msg+='<p class="sub">Has participado en las '+f.title+'. +2 '+(MODE==='roma'?'sestercios':'óbolos')+'. La fiesta queda en tu diario (pestaña Fiestas).</p>';}
        else msg+='<p class="sub">No era lo que se esperaba de ti. Inténtalo de nuevo.</p>';save();updateStats();$('dBody').innerHTML=head+msg;menu();};o.appendChild(b);});};
  $('dBody').innerHTML=head+'<p>'+(done?'¡Otra vez por aquí! Ya conoces bien esta fiesta.':f.short)+'</p>';menu();$('dialog').hidden=false;}
// ritos menos conocidos, misteriosos o extraños (se añaden al ciclo)
FESTS_ATENAS.push(
 {id:'haloa',title:'Haloa',month:'Posideón (diciembre)',god:'Deméter, Core y Dioniso',at:'place:eleusinion',h0:9,h1:18,n:45,
  short:'Fiesta de las mujeres en Eleusis, en pleno invierno, por la poda y la siembra.',
  txt:'En pleno invierno, cuando se poda la viña y el trigo recién sembrado empieza a brotar, las mujeres de Atenas celebran la Haloa, la fiesta de las eras, en honor de Deméter, de su hija Core y de Dioniso. Los arcontes preparan las mesas del banquete, llenas de pasteles, frutas y vino, y luego se marchan: el banquete es solo de mujeres. Durante la noche se cuentan bromas atrevidas y se dicen burlas sin miedo, como pide el rito, porque la risa y la abundancia llaman a la fertilidad de los campos. Hoy salen hacia Eleusis desde el Eleusinion de la ciudad.',
  off:{name:'Timarete',title:'Sacerdotisa de Deméter',look:{female:true,chiton:'#efe6d4',himation:'#8a6a2a',hair:'#d8d0c2'}},
  topics:[['¿Por qué solo mujeres?','Porque Deméter es la madre, y la tierra que da fruto se parece a nosotras. En la Haloa y en las Tesmoforias somos las mujeres las que hablamos con la diosa en nombre de la ciudad. Los hombres preparan las mesas y se van. Algunos refunfuñan, pero se van.'],['¿Qué tiene que ver Dioniso?','Que es invierno y se poda la viña. Dicen que Dioniso enseñó a un campesino ático, Icario, a hacer vino, y que los vecinos, al probarlo, creyeron que los había envenenado y lo mataron. Por eso en esta fiesta se le recuerda junto a Deméter: el pan y el vino, los dos regalos de los dioses al campo.'],['¿Es verdad que se dicen cosas atrevidas?','Sí, y es sagrado. Cuando Deméter buscaba a su hija, nada la consolaba, hasta que una vieja criada, Yambe, le hizo reír con sus bromas. Desde entonces, en sus fiestas las mujeres nos burlamos unas de otras y decimos lo que no diríamos en ningún otro sitio. Lo que pasa en la Haloa, se queda en la Haloa.'],['¿Puede ofrecer sacrificios cualquiera?','Hoy, no: el sacrificio de sangre está prohibido, solo se ofrecen frutos y pasteles. Hace poco juzgaron a un hierofante por sacrificar un animal en el altar del patio de Eleusis el día de la Haloa. Perdió el cargo.']],
  rite:{q:'Los arcontes terminan de preparar las mesas del banquete de las mujeres. ¿Qué haces?',o:[['Ayudar a llevar las cestas de frutos hasta las mesas y luego dejar a las mujeres con su fiesta','Timarete te da las gracias con una sonrisa. Al marcharte, oyes las primeras carcajadas detrás de los muros.'],['Intentar quedarte a escondidas para ver el banquete','Una anciana te descubre y te echa con una retahíla de insultos tan ingeniosos que, a pesar de todo, te ríes.'],['Sacrificar un cabrito en el altar para ayudar a la cosecha','«¡Hoy no!», grita la sacerdotisa. «En la Haloa no se derrama sangre. Por eso mismo condenaron al hierofante».']]},
  src:'Escolio a Luciano, Diálogos de las cortesanas 7.4; [Demóstenes] 59.116 (el hierofante Arquias); Himno homérico a Deméter 192-205 (Yambe); Apolodoro III 14.7 (Icario).'},
 {id:'misterios_dionisiacos',title:'Misterios de Dioniso (iniciación báquica)',month:'En privado, de noche',god:'Dioniso Baco',at:'place:ceramico',h0:20,h1:24,n:25,
  short:'Un tíaso inicia de noche a nuevos devotos de Baco, con antorchas, máscaras y la cesta mística.',
  txt:'Además de las fiestas públicas, Dioniso tiene misterios privados. Grupos de devotos, los tíasos, a menudo dirigidos por una sacerdotisa, inician de noche a quien quiera entrar. Se purifica al iniciado con barro y salvado, se le cubre la cabeza y se le muestra una cesta de aventar, el likno, con objetos sagrados. Luego se baila con antorchas al son de tambores y flautas, gritando «¡Evoé!». A los iniciados se les promete una vida mejor después de la muerte: algunos se entierran con laminillas de oro que explican al alma qué camino seguir en el más allá.',
  off:{name:'Fanóstrata',title:'Sacerdotisa de un tíaso báquico',look:{female:true,chiton:'#e8dfcc',himation:'#5a2a4a',hair:'#3b2a1e'}},
  topics:[['¿Qué prometéis a los iniciados?','Que Baco libera: de las preocupaciones en vida y del miedo a la muerte. El alma del iniciado, cuando llegue al reino de Perséfone, sabrá qué decir y de qué fuente beber. Dirá: «Soy hija de la Tierra y del Cielo estrellado», y la dejarán pasar.'],['¿Por qué el barro y el salvado?','Para limpiarte. Te untamos con barro y luego te lo quitamos con salvado: sales nuevo. Después dices la fórmula: «Escapé del mal, encontré algo mejor».'],['¿Los filósofos qué opinan?','Platón, el de la Academia, repite un dicho nuestro: «Muchos llevan el tirso, pero pocos son bacos». Es decir, muchos se inician y pocos cambian de verdad. No le falta razón. Otros se burlan de nosotras y nos llaman charlatanas que venden la salvación por unas monedas.'],['¿Es lo mismo que las Bacantes de Eurípides?','En el teatro todo es más terrible: allí las ménades despedazan al rey Penteo. Nosotras bailamos, cantamos y nos vamos a casa al amanecer, cansadas y felices. Bueno, casi todas.']],
  rite:{q:'Te cubren la cabeza con un velo y te acercan el likno, la cesta sagrada. ¿Qué haces?',o:[['Guardar silencio y, cuando te lo indican, decir: «Escapé del mal, encontré algo mejor»','Te quitan el velo. Las antorchas giran a tu alrededor y el tíaso grita «¡Evoé!». Ya eres un iniciado de Baco.'],['Levantar el velo para ver qué hay en la cesta','Fanóstrata te vuelve a bajar el velo. «Lo que se ve antes de tiempo no se entiende», te dice.'],['Preguntar cuánto cuesta la salvación','Se oyen risas. «Una gallina y unas tortas, como a todos», dice la sacerdotisa. «Lo demás lo pone el dios».']]},
  src:'Platón, Fedón 69c y República 364e-365a; Demóstenes 18.259-260 (las iniciaciones privadas que dirigía Glaucotea); Heródoto IV 79; laminillas órficas de oro de Hiponion y Petelia; Eurípides, Bacantes.'},
 {id:'tiades',title:'Las tíades del Parnaso',month:'Cada dos inviernos',god:'Dioniso',at:'place:castalia',h0:20,h1:24,n:30,
  short:'De noche, mujeres de Delfos y de Atenas suben al Parnaso a celebrar a Dioniso.',
  txt:'Cada dos inviernos, mientras Apolo, dicen, se ausenta de Delfos, el santuario es de Dioniso. Un grupo de mujeres, las tíades, junto a otras que vienen de Atenas, sube de noche a las cumbres nevadas del Parnaso con antorchas, tirsos (bastones coronados de piña y hiedra) y tambores, a celebrar al dios con danzas extáticas. Las atenienses van haciendo paradas por el camino para bailar. Los mitos cuentan cosas terribles de las ménades, como en Las bacantes de Eurípides; la realidad son mujeres respetables, organizadas y muy decididas: una vez quedaron atrapadas por la nieve y hubo que rescatarlas.',
  off:{name:'Eurínome',title:'Jefa de las tíades de Delfos',look:{female:true,chiton:'#e8dfcc',himation:'#3f5a2a',hair:'#3b2a1e'}},
  topics:[['¿Qué hacéis en la montaña?','Bailamos al son de los tambores y las flautas hasta quedar fuera de nosotras mismas: eso significa «éxtasis». Dioniso es el dios que libera, el que hace salir a cada uno de su papel de cada día. No te contaré más: es nuestro rito.'],['¿Es verdad lo de la nieve?','Una vez, en pleno invierno, la tormenta nos sorprendió en lo alto y tuvieron que subir hombres a buscarnos. Y en otra ocasión, unas tíades perdidas en la guerra llegaron de noche a Anfisa, una ciudad enemiga, y se durmieron agotadas en la plaza; las mujeres de la ciudad las rodearon para protegerlas hasta que amaneció.']],
  rite:{q:'Las tíades pasan con antorchas camino del monte. ¿Qué haces?',o:[['Apartarte con respeto y dejarlas pasar','Eurínome te dedica un gesto con el tirso. Las antorchas se pierden monte arriba, entre cantos.'],['Seguirlas a escondidas','A los pocos pasos, dos tíades te cierran el camino con los tirsos. No es tu rito.'],['Burlarte de ellas','Recuerdas lo que le pasó a Penteo en el mito, y decides callarte a tiempo.']]},
  src:'Pausanias X 4.3 y X 32.7; Plutarco, Virtudes de mujeres 13 y Sobre el primer frío 18; Eurípides, Las bacantes.'},
 {id:'orficos',title:'Iniciación órfica',month:'Cuando lo pida el cliente',god:'Dioniso y Perséfone',at:'npc:orfeotelesta',h0:9,h1:20,n:15,
  short:'Un purificador ambulante ofrece ritos secretos para una vida feliz después de la muerte.',
  txt:'Por las puertas de los ricos llaman los orfeotelestas, purificadores ambulantes con libros que atribuyen a Orfeo y a Museo. Por un precio, prometen limpiar las culpas, propias o de los antepasados, con sacrificios, cantos y juegos, y asegurar una vida feliz tras la muerte. Los órficos no comen carne y creen que el alma está encerrada en el cuerpo como en una cárcel. A algunos iniciados se les entierra con una laminilla de oro que les indica el camino en el Hades: no beber de la primera fuente, la del olvido, sino de la laguna de la Memoria, y decir a los guardianes: «Soy hijo de la Tierra y del Cielo estrellado».',
  off:{name:'Arcesilao',title:'Orfeotelesta',look:{chiton:'#f3eee2',himation:'#6a4d7a',beard:true,hair:'#5b4532',staff:true}},
  topics:[['¿Qué dicen los libros de Orfeo?','Que Dioniso niño fue despedazado por los Titanes, y que Zeus los fulminó con el rayo. De sus cenizas nacimos los hombres: tenemos algo de titanes, culpables, y algo de Dioniso, divino. La iniciación libera la parte divina.'],['¿Por qué no coméis carne?','Porque derramar sangre mancha el alma, y porque toda vida está emparentada. La vida órfica es pura: vestidos blancos, nada de carne, nada de huevos.']],
  rite:{q:'Arcesilao te ofrece purificarte de las culpas de tus antepasados por un buen precio. ¿Qué haces?',o:[['Escucharle con curiosidad, pero preguntarle qué sentido tiene comprar la pureza','Arcesilao duda un momento. «La pureza no se compra… se merece. El dinero solo paga mis libros». Has aprendido mucho de una religión distinta sin dejarte engañar.'],['Pagarle sin preguntar','Arcesilao se lleva tus monedas encantado. Platón decía que estos purificadores se aprovechan de los ricos asustados.'],['Echarlo a gritos','Se va, ofendido. Te quedas sin saber nada de los órficos.']]},
  src:'Platón, República 364b-365a; Eurípides, Hipólito 952-954; laminillas de oro de Hipponion y Petelia; papiro de Derveni.'},
 {id:'cronias',title:'Cronias',month:'Hecatombeón (julio)',god:'Crono',at:'place:olimpieion',h0:12,h1:22,n:40,
  short:'Amos y esclavos comen juntos en recuerdo de la edad de oro.',
  txt:'En honor de Crono, el padre de Zeus, que reinaba en la edad de oro, cuando la tierra daba frutos sin trabajo y no había esclavos. Ese día los amos invitan a sus esclavos a su mesa, comen con ellos y a veces les sirven. Los romanos tienen una fiesta parecida, las Saturnales. Por un día se imagina un mundo sin señores.',
  off:{name:'Manes',title:'Esclavo frigio',look:{short:true,noHimation:true,chiton:'#a08a62',hair:'#3b2a1e'}},
  topics:[['¿Cambia algo para ti?','Un día como, me siento y me sirven. Al día siguiente vuelvo a ser Manes. Pero ese día pienso que el mundo podría ser de otra manera. No es poco.'],['¿Quién era Crono?','El rey de los Titanes, que devoraba a sus hijos para que no lo destronaran. Zeus se salvó y lo venció. Pero dicen que su reinado fue feliz para los hombres.']],
  rite:{q:'Manes se sienta a la mesa junto a sus amos. ¿Qué haces tú?',o:[['Sentarte con todos y compartir la comida','Manes levanta su copa hacia ti. «Por Crono, y por el día de hoy».'],['Quedarte de pie, apartado','Los demás te miran extrañados. Hoy todos comen juntos.'],['Pedir a Manes que te sirva a ti','Manes te mira serio. «Hoy no». Y tiene razón.']]},
  src:'Filócoro en Macrobio, Saturnales I 10.22; Demóstenes XXIV 26; Hesíodo, Trabajos y días 109-126.'},
 {id:'diasias',title:'Diasias',month:'Antesterión (febrero)',god:'Zeus Miliquio',at:'place:cinosarges',h0:9,h1:17,n:45,
  short:'Fiesta de Zeus «el Benévolo», fuera de las murallas: tortas con forma de animales.',
  txt:'La mayor fiesta de Zeus en Atenas no se celebra en la ciudad, sino fuera de las murallas, junto al Iliso, en honor de Zeus Miliquio, «el que se deja aplacar», representado a veces como una gran serpiente. Las familias acuden en masa. Los ricos sacrifican animales enteros, que se queman del todo para el dios; los pobres ofrecen tortas de harina con forma de animales. Después hay mercado y los niños reciben juguetes.',
  off:{name:'Cálias',title:'Maestro de primeras letras',look:{chiton:'#e8e0cf',himation:'#6d7b9a',beard:true,hair:'#5b4532'}},
  topics:[['¿Por qué tortas con forma de animal?','Porque Zeus mira el corazón, no el bolsillo. Una torta con forma de buey hecha con lo que uno tiene vale como un buey. Así nadie se queda sin ofrecer.'],['¿Por qué una serpiente?','Zeus Miliquio es un dios de la tierra, que protege la casa y la riqueza. Las serpientes viven bajo tierra y guardan las casas. Por eso en sus relieves aparece como una serpiente enorme.']],
  rite:{q:'Tienes pocas monedas. ¿Qué ofreces a Zeus Miliquio?',o:[['Una torta con forma de buey, como hacen los pobres','Dejas la torta en el altar. Un anciano asiente: «El dios la recibe igual».'],['Nada, porque no puedes comprar un buey','Cálias te reprende con suavidad: «Por eso existen las tortas».'],['Pedir dinero prestado para un buey','Cálias se ríe. «¿Endeudarte para un dios que se llama el Benévolo?».']]},
  src:'Tucídides I 126.6 y su escolio; Aristófanes, Nubes 408 y 864; Jenofonte, Anábasis VII 8.4.'},
 {id:'carneas',title:'Carneas',month:'Metagitnión (agosto)',god:'Apolo Carneo',at:'place:eurotas',h0:8,h1:19,n:45,
  short:'La gran fiesta de Esparta: nueve días sin guerra y una carrera por las vides.',
  txt:'Durante nueve días, los espartanos acampan en tiendas como en una campaña, por grupos, y celebran a Apolo Carneo. Unos jóvenes, los «corredores de las uvas», persiguen a otro que lleva cintas y ramas de vid: si lo alcanzan, es buena señal para la ciudad. Durante la fiesta, Esparta no sale a la guerra por nada del mundo. Por eso en las Termópilas solo había trescientos espartanos: el grueso del ejército esperaba a que acabaran las Carneas.',
  off:{name:'Teleclo',title:'Enviado espartano',look:{chiton:'#a8392b',himation:'#7a1c14',beard:true,hair:'#3b2a1e'}},
  topics:[['¿Por qué no lucháis durante la fiesta?','Porque lo que se debe a los dioses va primero. Un espartano puede perder una batalla, pero no la piedad. Los atenienses llaman a esto superstición; nosotros, obediencia.'],['¿Qué significa la carrera?','Que la ciudad persigue la prosperidad. Si los jóvenes alcanzan al que lleva las uvas, el año será bueno. Si no… habrá que esforzarse más.']],
  rite:{q:'Un aliado te pide que convenzas a los espartanos de salir a luchar durante las Carneas. ¿Qué le dices?',o:[['Que esperen: ningún espartano romperá la fiesta de Apolo','Teleclo asiente con aprobación. Has entendido a Esparta.'],['Que les ofrezca más dinero','Teleclo te mira con desprecio. «El dinero no mueve a Esparta».'],['Que les llame cobardes','Teleclo se lleva la mano a la espada. Mejor no insistas.']]},
  src:'Heródoto VII 206 y VIII 72; Tucídides V 54 y V 75; Ateneo IV 141e-f; Hesiquio s.v. staphylodrómoi.'},
 {id:'jacintias',title:'Jacintias',month:'Hecatombeo espartano (primavera)',god:'Jacinto y Apolo',at:'place:menelaion',h0:9,h1:19,n:45,
  short:'Un día de luto y dos de alegría por Jacinto, el amigo de Apolo.',
  txt:'En Amiclas, cerca de Esparta, se recuerda a Jacinto, el joven amigo de Apolo al que el dios mató sin querer con un disco; de su sangre nació la flor. El primer día es de luto: no se llevan coronas, no se cantan himnos y se come sin pan ni dulces. Los otros dos son de alegría: muchachos tocan la lira y cantan, las muchachas desfilan en carros adornados, y se tejen y ofrecen ropas a Apolo. Los espartanos que estén en campaña vuelven a casa para celebrarlo.',
  off:{name:'Cinisca',title:'Princesa espartana',look:{female:true,chiton:'#e8dfcc',himation:'#a8392b',hair:'#5b4532'}},
  topics:[['¿Por qué luto y luego alegría?','Porque primero lloramos a Jacinto, que murió joven, y luego celebramos que la vida vuelve, como la flor que nació de él. Es la primavera.'],['¿Las mujeres participan?','Mucho. Desfilamos en carros, cantamos y bailamos. En Esparta las mujeres tenemos más libertad que en Atenas: hacemos ejercicio, montamos a caballo… y yo he ganado en Olimpia.']],
  rite:{q:'Es el primer día de las Jacintias. ¿Cómo te presentas?',o:[['Sin corona y en silencio, por el luto de Jacinto','Cinisca asiente. Mañana podrás llevar coronas y cantar con todos.'],['Con una corona de flores y cantando','Varios espartanos te miran con severidad. Hoy es día de luto.'],['Con un pastel de miel','Hoy no se comen dulces. Guárdalo para mañana.']]},
  src:'Ateneo IV 139d-f (Polícrates); Pausanias III 19.3-5; Jenofonte, Helénicas IV 5.11; Ovidio, Metamorfosis X 162-219.'});
FESTS_ROMA.push(
 {id:'mundus',title:'Mundus patet',month:'24 de agosto, 5 de octubre y 8 de noviembre',god:'Los dioses de abajo',at:'place:ro_curia',h0:6,h1:20,n:35,
  short:'«El mundo está abierto»: se levanta la piedra que tapa la entrada al mundo de los muertos.',
  txt:'Tres días al año se retira la piedra que tapa el mundus, una fosa sagrada que según la tradición abrió Rómulo al fundar la ciudad, donde echó primicias y tierra de su patria. Esos días, dice Varrón, está como abierta la puerta de los dioses tristes y del mundo de los muertos. Por eso son días religiosos y peligrosos: no se libran batallas, no se reclutan soldados, no se zarpa y no se celebran bodas.',
  off:{name:'Gneo Domicio Calvino',title:'Augur',look:FW.r},
  topics:[['¿Qué hay dentro del mundus?','Lo que echó Rómulo: los primeros frutos de la tierra y un puñado de tierra de donde venía cada colono. Es el centro de la ciudad, su raíz. Y por ahí se comunica con el mundo de abajo.'],['¿Qué pasa si alguien no respeta el día?','Los antiguos dicen que una guerra empezada en un día así acabará mal. No lo comprobaré yo: hoy nadie firma nada, nadie se casa y ningún barco sale de Ostia.']],
  rite:{q:'Un amigo quiere celebrar su boda precisamente hoy. ¿Qué le dices?',o:[['Que la aplace: hoy el mundus está abierto y es un día nefasto para casarse','El augur te mira con aprobación. Tu amigo, de mala gana, retrasa la boda unos días.'],['Que se case, que es un día como otro','El augur suspira. Ninguna familia romana sensata lo haría.'],['Que se case dentro del mundus','El augur palidece. Ni en broma.']]},
  src:'Varrón en Macrobio, Saturnales I 16.17-18; Festo s.v. mundus; Plutarco, Rómulo 11; Ovidio, Fastos IV 821-824.'},
 {id:'bacanales',title:'Ritos de Baco (tíaso)',month:'En secreto, varias veces al año',god:'Baco (Líber)',at:'place:ro_circo',h0:20,h1:24,n:20,
  short:'Una cofradía báquica celebra sus misterios; Roma no olvida el escándalo del 186 a.C.',
  txt:'Los seguidores de Baco se reúnen en cofradías, los tíasos, para celebrar sus misterios: hiedra, máscaras, música, vino y una iniciación en la que se descubre un objeto sagrado oculto en un cesto. Roma los mira con desconfianza. Hace más de doscientos cincuenta años, en el 186 a.C., estalló el escándalo de las Bacanales: se acusó a las reuniones nocturnas del bosque de Estímula, junto al Aventino, de toda clase de crímenes. El Senado ordenó miles de procesos y prohibió el culto salvo con permiso: los grupos no podían pasar de cinco personas ni tener fondos comunes. Hoy los tíasos vuelven a existir, más discretos.',
  off:{name:'Annia',title:'Sacerdotisa de una cofradía báquica',look:{female:true,chiton:'#e8dfcc',himation:'#4a2a5a',hair:'#3b2a1e'}},
  topics:[['¿Qué pasó en el 186 a.C.?','Una mujer denunció las reuniones ante el cónsul, y se desató el pánico: decían que en ellas se conspiraba, se falsificaban testamentos y se cometían crímenes. Muchos fueron condenados. Nadie sabe cuánto era verdad y cuánto miedo a algo nuevo. En Calabria se encontró el bronce con la orden del Senado.'],['¿Qué se ve en la iniciación?','Eso no se cuenta. En una villa de Pompeya hay unas pinturas que muestran una iniciación, con una mujer que va a descubrir el objeto oculto en el cesto. Pompeya ya no existe, pero las pinturas seguirán bajo la ceniza.']],
  rite:{q:'Te invitan a una reunión del tíaso, por la noche, en secreto. ¿Qué haces?',o:[['Preguntar si la cofradía tiene permiso y respetar sus reglas y su secreto','Annia sonríe: «Tenemos permiso, y somos pocos, como manda la ley». Te cuenta lo que se puede contar. Has conocido un culto sin caer ni en el pánico ni en la ingenuidad.'],['Denunciarlos al magistrado sin saber nada','El magistrado comprueba que tienen permiso y te despide. Así empezó el miedo del 186.'],['Ir y luego contarlo todo por la ciudad','Te cierran la puerta. Los misterios son misterios.']]},
  src:'Livio XXXIX 8-19; senadoconsulto de las Bacanales (CIL I² 581, Tiriolo); frescos de la Villa de los Misterios de Pompeya.'},
 {id:'argeos',title:'Argeos',month:'14 de mayo',god:'Rito muy antiguo, de dioses inciertos',at:'place:ro_hercules',h0:9,h1:14,n:50,
  short:'Las vestales arrojan al Tíber veintisiete muñecos de junco atados de pies y manos.',
  txt:'Un rito tan antiguo que ni los romanos saben bien su origen. En marzo se lleva una procesión por veintisiete pequeños santuarios de la ciudad. El 14 de mayo, los pontífices, el pretor y las vestales van al puente Sublicio, el más antiguo de Roma, y las vestales arrojan al Tíber veintisiete muñecos de junco con forma humana, atados de pies y manos, que llaman argeos. La flamínica asiste vestida de luto.',
  off:{name:'Cornelia',title:'Virgen vestal',look:{female:true,chiton:'#f3eee2',himation:'#f3eee2',veil:true,hair:'#5b4532'}},
  topics:[['¿Por qué muñecos?','Unos dicen que sustituyen a personas que en tiempos muy antiguos se sacrificaban al río, y que Hércules enseñó a los romanos a usar figuras en su lugar. Otros, que eran los griegos que vinieron con él. Ovidio cuenta varias versiones y no se decide.'],['¿Por qué el puente Sublicio?','Porque es el más antiguo y sagrado: es de madera, sin un solo clavo de hierro, y lo cuidan los pontífices, que precisamente se llaman así: «los que hacen puentes».']],
  rite:{q:'Los muñecos caen al agua y la corriente se los lleva. ¿Qué haces?',o:[['Guardar silencio con todos hasta que se pierdan de vista','Cornelia asiente. El rito está cumplido, como cada año desde hace siglos.'],['Intentar rescatar uno del río','Te miran horrorizados. El río tiene que llevárselos.'],['Preguntar en voz alta si es un rito de sacrificios humanos','Un pontífice te contesta con frialdad: «Son de junco. Y así seguirán».']]},
  src:'Ovidio, Fastos V 621-662; Dionisio de Halicarnaso I 38; Varrón, La lengua latina V 45-54 y VII 44.'},
 {id:'bonadea',title:'Bona Dea',month:'Principios de diciembre',god:'Bona Dea, la Buena Diosa',at:'place:ro_palatino',h0:20,h1:24,n:30,women:true,
  short:'Rito nocturno solo de mujeres en casa de un alto magistrado. Ningún hombre puede estar.',
  txt:'Una noche de diciembre, la esposa de un cónsul o un pretor recibe en su casa a las mujeres más importantes de Roma y a las vestales para celebrar a la Buena Diosa, en nombre de todo el pueblo. El dueño de la casa y todos los hombres salen; se cubren incluso las estatuas y retratos de varones. El mirto está prohibido; al vino lo llaman «leche» y a la jarra, «tarro de miel». Hace casi ciento cincuenta años, un joven noble, Clodio, se coló disfrazado de mujer en la casa de César: lo descubrieron, hubo juicio y César se divorció de su esposa diciendo que la mujer del César no solo debe ser honrada, sino parecerlo.',
  off:{name:'Pomponia',title:'Matrona, de camino a la ceremonia',look:FW.rf},
  topics:[['¿Quién es la Buena Diosa?','Una diosa de la salud, de la fertilidad y de las mujeres. Su nombre verdadero no se pronuncia. En su templo del Aventino se cuidan hierbas medicinales y viven serpientes sagradas.'],['¿Por qué no hay hombres?','Porque es el rito de las mujeres por el bien de todo el pueblo. Lo que pasa allí es asunto nuestro. Y por lo de Clodio, ya ves que ni los nobles se libran si lo intentan.']],
  rite:{q:'Ves salir de la casa al cónsul y a todos los hombres. ¿Qué haces?',o:[['Irte tú también, como manda el rito','Pomponia te sonríe al pasar. Esta noche la casa es de las mujeres y de la diosa.'],['Esperar escondido a ver qué pasa','Recuerdas lo que le pasó a Clodio, y te vas a toda prisa.'],['Pedir que te dejen entrar como ayudante','Un esclavo te cierra la puerta con firmeza. Ni ayudantes.']]},
  src:'Plutarco, César 9-10 y Cicerón 19; Cicerón, Sobre la respuesta de los harúspices; Macrobio, Saturnales I 12.21-29.'},
 {id:'cerialia',title:'Cerialia',month:'12 al 19 de abril',god:'Ceres',at:'place:ro_circo',h0:9,h1:18,n:60,
  short:'Fiesta de Ceres, diosa del trigo y protectora de la plebe.',
  txt:'Durante una semana, juegos en honor de Ceres, la diosa del trigo y de las cosechas, cuyo templo junto al Circo Máximo es el santuario de la plebe: allí se guardaban los archivos de los tribunos y se repartía grano a los pobres. Hay carreras en el Circo, se viste de blanco y se arrojan nueces. El último día se practica un rito extraño y cruel: se sueltan zorras con antorchas atadas a la cola. Nadie sabe bien por qué; Ovidio cuenta una leyenda de un niño que quiso castigar a una zorra y provocó un incendio en los trigales.',
  off:{name:'Eutiques',title:'Comerciante de grano',look:{chiton:'#d8c9a8',himation:'#4f6a7d',beard:true,hair:'#5b4532'}},
  topics:[['¿Por qué Ceres es de la plebe?','Porque cuando los plebeyos lucharon por sus derechos contra los patricios, hace siglos, su templo fue su centro. Los ediles de la plebe tenían allí su sede. El trigo es de todos: Ceres también.'],['¿De dónde viene el nombre?','De Ceres viene «cereal». Su mito es el de la griega Deméter: buscó a su hija Proserpina, raptada por el rey de los muertos.']],
  rite:{q:'Hoy se viste de blanco en honor de Ceres. ¿Qué haces?',o:[['Ponerte una túnica blanca y ofrecer unas espigas en su templo','Un sacerdote recoge tus espigas. «Que no falte el pan en tu mesa».'],['Ir con ropa de colores, como en las Floralia','Destacas como una amapola en un trigal. No es el día.'],['Llevarte espigas del templo','El sacerdote te las quita de las manos.']]},
  src:'Ovidio, Fastos IV 393-620 y 679-712; Livio III 55.13; Plinio, Historia natural XVIII 8.'},
 {id:'parentalia',title:'Parentalia',month:'13 al 21 de febrero',god:'Los antepasados',at:'place:ro_appia',h0:9,h1:18,n:45,
  short:'Las familias visitan las tumbas de sus padres con flores, sal y pan con vino.',
  txt:'Durante nueve días, los templos cierran, no se celebran bodas y las familias visitan las tumbas de sus antepasados a lo largo de las calzadas, fuera de la ciudad. Se les lleva una corona, unos granos de trigo, un poco de sal, pan mojado en vino y violetas. Los muertos, dice Ovidio, no piden mucho: la piedad vale más que los regalos ricos. Al día siguiente de terminar, en las Caristias, la familia se reúne a comer y se reconcilian los que estaban peleados.',
  off:{name:'Tito Cornelio',title:'Nieto de un veterano',look:FW.r},
  topics:[['¿Por qué fuera de la ciudad?','Porque la ley prohíbe enterrar dentro de Roma desde las Doce Tablas. Por eso las calzadas, como la Vía Apia, están llenas de tumbas: así los muertos ven pasar a los vivos, y los vivos los recuerdan.'],['¿Qué son las Caristias?','El día del cariño. Toda la familia come junta, se ofrece a los Lares y se olvidan las peleas. Quien no quiera reconciliarse, mejor que no venga.']],
  rite:{q:'Ante la tumba de una familia, ¿qué ofreces?',o:[['Unas violetas, un poco de sal y pan mojado en vino','Tito Cornelio asiente. «A los muertos les basta con poco, si se da con cariño».'],['Una moneda de oro','«¿Para qué la quieren?», te pregunta Tito, divertido.'],['Nada: los muertos no comen','Tito te mira serio. «No es por ellos. Es por nosotros».']]},
  src:'Ovidio, Fastos II 533-638; Valerio Máximo II 1.8 (Caristias); Ley de las Doce Tablas X 1.'},
 {id:'robigalia',title:'Robigalia',month:'25 de abril',god:'Robigo',at:'place:ro_mausoleo',h0:8,h1:14,n:40,
  short:'Un sacrificio en las afueras para alejar el tizón del trigo.',
  txt:'A cinco millas de Roma, en la Vía Claudia, el flamen de Quirino ofrece un sacrificio a Robigo, el poder que trae el tizón, el hongo que pudre las espigas de trigo en primavera. Se le ofrecen las entrañas de una oveja y de un perro, y se le pide que se aleje de los sembrados. Después hay carreras de muchachos. Para una ciudad que depende del trigo, una plaga puede significar el hambre.',
  off:{name:'Lucio Nonio',title:'Agrimensor',look:{short:true,noHimation:true,chiton:'#a08a62',hair:'#3a2a1e'}},
  topics:[['¿Por qué un perro?','Porque en estas fechas sale la estrella del Perro, que trae el calor, y el calor con humedad hace crecer el tizón. Es lo que dice Ovidio. Los ritos antiguos tienen su lógica, aunque nos parezca extraña.'],['¿Funciona?','Los campesinos también rotan los cultivos, eligen buenas semillas y queman los rastrojos. El rito no sustituye al trabajo; lo acompaña.']],
  rite:{q:'¿Qué piden los romanos a Robigo?',o:[['Que se aleje de los trigales y no los pudra','El flamen asiente. «Que coma las espadas y no el trigo», dice la oración.'],['Que traiga más lluvia','No: la humedad es precisamente lo que alimenta el tizón.'],['Que bendiga los rebaños','Eso se pide en las Parilias.']]},
  src:'Ovidio, Fastos IV 901-942; Columela X 342-343; Plinio, Historia natural XVIII 284-285.'},
 {id:'terminalia',title:'Terminalia',month:'23 de febrero',god:'Término',at:'place:ro_jupiter',h0:8,h1:17,n:35,
  short:'Los vecinos honran juntos el mojón que separa sus tierras.',
  txt:'Término es el dios de los límites: vive en cada mojón de piedra que separa un campo de otro. En su fiesta, los dos vecinos se reúnen junto a la piedra, la coronan cada uno por su lado, levantan un altar, echan trigo y miel y comparten un banquete. Cuentan que cuando se construyó el templo de Júpiter en el Capitolio, todos los dioses que había allí aceptaron marcharse menos Término, que no quiso moverse: por eso su piedra está dentro del templo, bajo un agujero en el techo, porque debe ver el cielo.',
  off:{name:'Lucio Nonio',title:'Agrimensor',look:{short:true,noHimation:true,chiton:'#a08a62',hair:'#3a2a1e'}},
  topics:[['¿Por qué el dios no se movió?','Los romanos lo interpretaron como un presagio: las fronteras de Roma nunca retrocederían. Y por eso también ningún mojón debe moverse jamás. Mover un límite era antiguamente un crimen terrible.'],['¿Qué hacen los agrimensores?','Medimos y marcamos los límites. Cuando dos vecinos discuten, nosotros sabemos dónde está cada mojón. Término y yo trabajamos juntos.']],
  rite:{q:'Dos vecinos discuten junto a un mojón. ¿Qué les propones?',o:[['Que lo coronen juntos y celebren la fiesta, como manda la tradición','Los vecinos se miran y acaban brindando junto a la piedra. Término une más que separa.'],['Mover el mojón un poco para contentar a uno','El agrimensor se escandaliza. Mover un mojón es sacrilegio.'],['Que vayan a juicio','Lucio Nonio suspira. «Para eso está la fiesta: para evitar juicios».']]},
  src:'Ovidio, Fastos II 639-684; Livio I 55; Dionisio de Halicarnaso II 74.'},
 {id:'fontinalia',title:'Fontinalia',month:'13 de octubre',god:'Fons, dios de las fuentes',at:'place:ro_lacus',h0:8,h1:17,n:40,
  short:'Se arrojan guirnaldas a las fuentes y se coronan los pozos.',
  txt:'En honor de Fons, el dios de las fuentes, los romanos arrojan guirnaldas de flores a los manantiales y coronan los brocales de los pozos. Es una fiesta sencilla y bonita, de agradecimiento por el agua, que en una ciudad de un millón de habitantes llega hoy por los acueductos, pero que antes dependía solo de pozos y fuentes.',
  off:{name:'Frontino',title:'Ingeniero',look:FW.r},
  topics:[['¿Por qué dar las gracias al agua?','Porque sin ella no hay ciudad. Los antiguos lo sabían y la veneraban. Yo la mido y la reparto, pero también le tengo respeto.'],['¿Siguen importando las fuentes?','Muchísimo. La fuente de Juturna, aquí en el Foro, es donde dicen que los Dioscuros dieron de beber a sus caballos tras anunciar una victoria. Cada fuente tiene su ninfa y su historia.']],
  rite:{q:'¿Qué ofreces en las Fontinalia?',o:[['Una guirnalda de flores, que arrojas a la fuente','El agua se lleva la guirnalda despacio. Frontino sonríe: «Buen agradecimiento para un buen servicio».'],['Una moneda, para pedir un deseo','Muchos lo hacen, pero hoy lo propio son las flores.'],['Nada, el agua es gratis','Frontino te mira serio: «Nada es gratis. Pregunta cuánto cuesta un acueducto».']]},
  src:'Varrón, La lengua latina VI 22; Festo s.v. Fontinalia; Ovidio, Fastos I 705-708 (Juturna).'},
 {id:'regifugium',title:'Regifugium',month:'24 de febrero',god:'Rito del antiguo rey',at:'place:ro_curia',h0:8,h1:14,n:40,
  short:'El «rey de los sacrificios» ofrece un sacrificio en el Comicio y sale huyendo.',
  txt:'Roma ya no tiene reyes desde hace casi seiscientos años, pero conserva un sacerdote que lleva ese nombre: el rex sacrorum, el «rey de los sacrificios», que hace los ritos que antiguamente hacían los reyes. No puede tener ningún cargo político. En el Regifugium ofrece un sacrificio en el Comicio y luego sale corriendo. Los romanos lo relacionaban con la expulsión de Tarquinio el Soberbio, el último rey.',
  off:{name:'Publio Cornelio Tácito',title:'Joven senador',look:FW.r},
  topics:[['¿Por qué huye?','Nadie lo sabe con seguridad. Quizá porque el sacrificio de fin de año era peligroso para quien lo hacía. Quizá para recordar la huida de Tarquinio. Los ritos sobreviven a sus explicaciones.'],['¿Por qué Roma no quiere reyes?','Desde que echó a Tarquinio, la palabra «rey» es odiosa en Roma. Por eso Augusto y los emperadores se llaman príncipes, el primero de los ciudadanos. Aunque mandan tanto como un rey… o más.']],
  rite:{q:'El rex sacrorum termina el sacrificio y echa a correr. ¿Qué haces?',o:[['Dejarle pasar y observar en silencio','Tácito asiente. «Has visto el último rastro de los reyes de Roma».'],['Correr detrás de él','La gente se ríe de ti. Nadie le persigue: el rito es que huya.'],['Gritarle «¡viva el rey!»','Un silencio helado cae sobre el Comicio. En Roma, esa palabra no se grita.']]},
  src:'Ovidio, Fastos II 685-856; Plutarco, Cuestiones romanas 63; Livio II 2.'});
// el ciclo ocupa los días pares libres de otros acontecimientos
function baseEvent(d){return EVENTS().find(e=>e.once?d===e.day:d>=e.day&&(d-e.day)%e.every===0)||null;}
festOfDay=function(d){if(d<2||d%2||baseEvent(d))return null;let n=0;for(let k=2;k<d;k+=2)if(!baseEvent(k))n++;const L=FESTS();return L[n%L.length];};
festNextDay=function(f){const d=state.day||1;for(let k=d;k<d+600;k++)if(festOfDay(k)===f)return k;return d;};
function festsHTML(){const L=FESTS(),fs=state.fest||{},ro=MODE==='roma';
  return '<p style="margin:0 0 12px;max-width:68ch;line-height:1.5">'+(ro?'El calendario romano estaba lleno de fiestas: unas eran de toda la ciudad, otras de los barrios, de las familias o de los cultos llegados de Oriente.':'Atenas celebraba más fiestas que ninguna otra ciudad griega: casi un día de cada tres había alguna.')+' En el juego, el año religioso va condensado: cada dos días se celebra una fiesta en su lugar, con su multitud y un oficiante (rombo !) que te la explica.'+(MODE==='roma'?' En Roma, cada fiesta cae en su mes: si el mes no tiene ninguna del ciclo, esos días no hay celebración.':'')+' Participa en el rito para que quede aquí anotada.</p><div class="entries">'+
   L.map(f=>{const ok=fs[f.id],d=festNextDay(f);return '<div class="entry'+(ok?'':' locked')+'"><span class="label">'+f.month+' · '+f.god+(ok?' · celebrada ✓':'')+'</span><h3>'+f.title+'</h3><p>'+(ok?f.txt:f.short)+'</p><div class="where">'+(d===(state.day||1)?'Hoy, de '+f.h0+' a '+f.h1+' h':'Próximo día '+d+', de '+f.h0+' a '+f.h1+' h')+(ok?' · Fuentes: '+f.src:'')+'</div></div>';}).join('')+'</div>';}

// ---- mujeres griegas: ensayo, temas de conversación y curiosidades (a partir de Desperta Ferro Arqueología e Historia n.º 11)
ESSAYS.push({id:'mujeres2',cat:'Contexto',title:'Mujeres griegas: leyes, ritos y Esparta',body:[
  'Los griegos describían su ciudad como una comunidad de varones: votar, juzgar y combatir era cosa de hombres. Pero las mujeres no estaban fuera de la polis. Desde la ley de Pericles del 451, solo era ciudadano quien tenía padre y madre atenienses, y a las hijas y esposas de ciudadanos se las empezó a llamar <i>astaí</i> o <i>politides</i>: «ciudadanas» sin voto, pero imprescindibles para que hubiera ciudadanos.',
  '<b>La boda.</b> El matrimonio era un acuerdo entre familias: el padre o tutor (kyrios) prometía a la hija con un apretón de manos y una fórmula ritual, ante testigos, «para tener hijos legítimos», y fijaba la dote. A la novia no se le preguntaba. Muchas atenienses se casaban hacia los catorce o quince años con hombres que les doblaban la edad. La dote no la administraba ella, sino su marido, y volvía a su familia si había divorcio.',
  '<b>El divorcio.</b> Era legal y no deshonraba, aunque podía enemistar a las familias. Lo podía pedir el marido (repudio), la mujer (con ayuda de un magistrado) o incluso el padre de la esposa, que podía «sacar» a su hija de un matrimonio que su familia ya no considerara digno, una forma de proteger a las maltratadas. Los hijos se quedaban siempre en casa del padre.',
  '<b>Herederas.</b> En Atenas, la hija sin hermanos (epiclera) no era dueña de la herencia, sino la vía para que pasara a sus hijos: debía casarse con el pariente más próximo de su padre. En Esparta y en Gortina, en Creta, en cambio, la hija podía heredar de verdad. Aristóteles se quejaba de que en su tiempo dos quintas partes de las tierras de Esparta estaban en manos de mujeres.',
  '<b>Esparta.</b> Las espartanas hacían ejercicio al aire libre, corrían y luchaban de jóvenes, se casaban más tarde que las atenienses (hacia los dieciocho o veinte años) y tenían fama de hablar con libertad. Plutarco reunió decenas de frases de espartanas; a la reina Gorgo le atribuye que, cuando una extranjera le preguntó por qué las espartanas mandaban en sus maridos, respondió que porque solo ellas daban a luz hombres. En Esparta no se ponía el nombre en las tumbas, salvo a los caídos en la guerra y a las mujeres muertas al dar a luz. Muchas de estas noticias son idealizaciones de atenienses admiradores de Esparta, y no hay que tomarlas al pie de la letra.',
  '<b>Sacerdotisas.</b> En la religión las mujeres eran indispensables. Muchas diosas tenían sacerdotisas, elegidas por sorteo o por su familia, a veces de por vida: Lisímaca sirvió a Atenea Polias durante sesenta y cuatro años. En sus tumbas aparecen con una gran llave, la del templo que custodiaban. Ellas presidían sacrificios, y cuando el hacha golpeaba a la víctima, las mujeres lanzaban un grito ritual, la <i>ololygé</i>. A la adúltera se la castigaba impidiéndole asistir a los sacrificios públicos.',
  '<b>Muerte y luto.</b> Las mujeres lavaban y vestían al difunto y lo lloraban en público, golpeándose el pecho y arrancándose el pelo, mientras los hombres guardaban un silencio respetuoso. A algunos les parecía excesivo: desde Solón, Atenas limitó los lamentos y prohibió arañarse las mejillas.',
  '<b>Fuera de la norma.</b> La mayoría de las mujeres pobres trabajaban fuera de casa: vendían en el mercado, eran nodrizas, comadronas, tejedoras o hilanderas. Las heteras («compañeras») eran mujeres libres o liberadas, a menudo extranjeras, educadas en la música y la conversación, que acudían a los banquetes masculinos y no podían casarse legalmente con un ciudadano; las <i>pornai</i>, en su mayoría esclavas, vivían en condiciones muy duras. En los tribunales, acusar a la mujer de un rival de haber sido hetera era una forma habitual de atacarlo, como en el discurso contra Neera.'],
 src:{a:['Aristóteles, Política II 1269b-1270a','Jenofonte, Económico VII; Constitución de los lacedemonios 1','Plutarco, Licurgo 14-16 y Máximas de espartanas','Iseo III y VIII; Demóstenes XLIII y LIX','Aristófanes, Lisístrata 638-647','Tucídides IV 133.2 (Crisis de Argos)','Plinio, Historia natural XXXIV 76 (Lisímaca)'],m:['Desperta Ferro Arqueología e Historia n.º 11, La mujer en Grecia (2017): artículos de F. Frisone, C. Sánchez, A. J. Domínguez Monedero, P. González, F. Gherchanoc y M. Dillon','S. B. Pomeroy, Spartan Women (2002)','M. Dillon, Girls and Women in Classical Greek Religion (2002)']}});
// temas de conversación nuevos para las mujeres del juego
{const T={
 sacerdotisa:[['¿Cuánto tiempo sirve una sacerdotisa?','Toda la vida, en mi caso. Una de mis antecesoras, Lisímaca, sirvió a la diosa sesenta y cuatro años; tiene estatua en la Acrópolis. En las tumbas de las sacerdotisas se esculpe una gran llave: la del templo que guardamos.'],
  ['¿Qué hacéis en un sacrificio?','Lo presido yo. Arrojo los granos de cebada al fuego, se rocía a la víctima y, cuando cae el hacha, las mujeres lanzamos un grito agudo, la ololygé, para que los dioses atiendan. Luego me corresponde una parte de la carne y la piel.']],
 aguadora:[['¿A qué edad os casáis?','Yo me casé con catorce años, con un hombre de treinta. Lo normal. Mi padre lo acordó con él dándose la mano delante de testigos. A mí nadie me preguntó; así se hace. Tuve suerte: es un buen hombre.'],
  ['¿Y si un matrimonio va mal?','Se puede deshacer. Si el marido la repudia, la mujer vuelve con su dote a casa de su padre. Si es ella la que quiere irse, tiene que ir ante el arconte, y eso es más difícil. Y su padre también puede llevársela si el marido la maltrata. Los hijos, eso sí, se quedan con el padre.']],
 novia:[['¿Cómo se acuerda una boda?','Entre el padre de ella y el novio, con un apretón de manos: «Te doy a mi hija para tener hijos legítimos», y se fija la dote. Antes de la boda, la muchacha sube a la Acrópolis con sus padres a ofrecer a Atenea y deja una dracma para Afrodita Urania.'],
  ['¿Qué regalos recibe la novia?','El día después de la boda vienen las amigas y parientes con regalos: cajitas, perfumes, vasos para el baño nupcial y un epínetro, la pieza de barro que se pone sobre la rodilla para cardar la lana. Algunos son tan bonitos que luego se ofrecen a una diosa.']],
 nodriza:[['¿Qué aprenden las niñas?','A hilar, a tejer, a llevar la despensa, a cuidar de los pequeños y algo de remedios. Las de buena familia, además, sirven a las diosas: a los siete años algunas son arréforas, a los diez muelen el grano sagrado, luego son «osas» de Ártemis en Braurón y, ya mayores, llevan la cesta en las procesiones.']],
 cinisca:[['¿Es verdad que las espartanas mandáis en vuestros maridos?','Cuentan que una ateniense se lo preguntó a la reina Gorgo, la mujer de Leónidas, y que ella contestó: «Porque somos las únicas que damos a luz hombres». No sé si lo dijo. Pero lo repetimos con gusto.'],
  ['¿Las espartanas podéis heredar?','Sí, y no como en Atenas, donde la hija sin hermanos es solo el camino para que la herencia pase a sus hijos. Aquí una hija hereda de verdad. Yo tengo mis propios caballos, y con ellos gané en Olimpia.']]};
 for(const id in T){if(!MORE[id])MORE[id]=[];MORE[id].push(...T[id]);}}
CURIOS.push(
 {id:'c_lisimaca',at:'polias',h:'Sesenta y cuatro años de sacerdotisa',t:'Lisímaca fue sacerdotisa de Atenea Polias durante sesenta y cuatro años, y la ciudad le dedicó una estatua de bronce. Las sacerdotisas de la diosa servían de por vida y eran de las mujeres más conocidas de Atenas.',s:'Plinio, Historia natural XXXIV 76'},
 {id:'c_crisis',at:'hereo',h:'La sacerdotisa que se durmió',t:'Crisis, sacerdotisa de Hera en Argos durante cuarenta y ocho años, se quedó dormida junto a una lámpara encendida. Las guirnaldas prendieron y el templo ardió hasta los cimientos. Ella huyó a Tegea por miedo a los argivos.',s:'Tucídides IV 133.2'},
 {id:'c_luto',at:'ceramico',h:'Leyes contra el llanto',t:'En los funerales, las mujeres lloraban a gritos, se arañaban las mejillas y se arrancaban el pelo. Tanto que Atenas, desde Solón, prohibió arañarse y limitó los lamentos al muerto que se enterraba: algunas aprovechaban para llorar también a todos sus difuntos anteriores.',s:'Plutarco, Solón 21; Demóstenes XLIII 62'},
 {id:'c_helena',at:'platanistas',h:'Carreras para Helena',t:'En Esparta, las muchachas solteras corrían carreras junto al Eurotas en honor de Helena, que era espartana, con la esperanza de encontrar un marido como Menelao. Al casarse, se acababan las carreras.',s:'Teócrito, Idilio 18; Pausanias III 13.7'},
 {id:'c_nicandra',at:'delos_lago',h:'La primera mujer que firmó',t:'Hacia el 650 a.C., Nicandra de Naxos ofreció a Ártemis en Delos una gran estatua de mármol y grabó su nombre en ella. Es la dedicación más antigua que se conoce hecha por una mujer griega.',s:'Estatua de Nicandra (Museo Arqueológico Nacional de Atenas)'},
 {id:'c_gortina',m:'a',h:'Las leyes de Gortina',t:'En la ciudad cretense de Gortina se grabó en piedra todo su código de leyes. Allí las mujeres podían heredar y tener bienes propios, y si un padre rechazaba al hijo nacido después de un divorcio, era la madre quien decidía si criarlo.',s:'Código de Gortina (siglo V a.C.)'},
 {id:'c_epinetro',m:'a',h:'Una teja en la rodilla',t:'Para cardar la lana, las mujeres griegas se ponían sobre la rodilla un epínetro, una pieza de barro o de madera con forma de media teja y la superficie rugosa. Los de barro, a menudo pintados con escenas de bodas, eran regalos de boda que luego se ofrecían en santuarios o tumbas.',s:'Epínetro de Eretria (Museo Arqueológico Nacional de Atenas)'},
 {id:'c_sakkos',m:'a',h:'El pelo recogido',t:'En las pinturas de los vasos, las mujeres respetables aparecen con el pelo recogido y a menudo cubierto por un pañuelo, el sakkós. La piel se pinta de blanco, para mostrar que no trabajan al sol, mientras que los hombres aparecen bronceados.',s:'Cerámica ática de figuras negras y rojas'});

// ---- alivio cómico: dos admiradores entusiastas (personajes inventados)
const FAN_PLATON={id:'platonakis',name:'Platonákis',title:'Admirador número uno de Platón',glyph:'Π',look:{chiton:'#efe6d4',himation:'#2f4c86',beard:true,hair:'#3b2a1e'},
 cat:'Filosofía',lesson:'Las Ideas de Platón, explicadas por su mayor fan',where:'En la Academia, siempre a dos pasos de Platón',
 summary:'Para Platón, además de las cosas que vemos, que cambian y nunca son perfectas, existen las Ideas o Formas: modelos perfectos y eternos (la Belleza, la Justicia, lo Igual) que solo se conocen con la razón. Las cosas son copias imperfectas de ellas. Platón expone sus ideas en diálogos en los que casi siempre habla Sócrates, su maestro.',
 intro:'¡Chsss! No hagas ruido, que el Maestro está pensando. O durmiendo: pone la misma cara. Soy Platonákis. Antes me llamaba Aristónimo, pero me cambié el nombre. ¿Sabes que «Platón» significa «ancho»? Yo como el doble para ir ensanchándome.',
 topics:[
  ['¿Por qué te llamas Platonákis?','Porque «-ákis» es un cariño, como decir «Platoncito». Me lo puse yo solo. El Maestro me llama «eso que me sigue». Estoy casi seguro de que es un apodo cariñoso.'],
  ['¿Qué es la teoría de las Ideas?','¡Mi favorita! Mira: ningún caballo es perfecto, todos cojean un poco o tienen mal genio. Pero en tu cabeza tienes la Idea de Caballo, perfecta y eterna. Las cosas son copias, y las Ideas, los modelos. Yo he visto la Idea de Pan. Bueno, vi un pan buenísimo y me la imaginé. Tenía sésamo. Le pregunté al Maestro si las Ideas llevan sésamo y estuvo suspirando hasta el Dípilon.'],
  ['¿Qué haces todo el día?','Sigo al Maestro y lo apunto todo en mis tablillas. Todo. Ayer apunté «pásame el aceite». Puede ser el principio de un diálogo. Lo titularé Aceitón, o sobre la grasa.'],
  ['¿Has leído sus diálogos?','¡Todos! La Apología, el Critón, el Eutifrón, el Gorgias… En casi todos habla Sócrates, y el Maestro no sale nunca. Yo creo que es tímido. Mi diálogo también lo protagoniza Sócrates: se titula Platonákis, o sobre lo bien que habla Platón.'],
  ['Cuéntame algo de la Academia','Aquí no se cobra, se piensa. Hay jardín, olivos, un gimnasio y mucha geometría. Dicen que el Maestro quiere poner un cartel en la entrada: «Que no entre nadie que no sepa geometría». Yo estoy estudiando a toda prisa. Ya distingo un triángulo de un cuadrado. Casi siempre.']],
 quiz:{q:'Cuando se pone serio, ¿qué dice Platonákis que son las Ideas de Platón?',a:['Modelos perfectos y eternos de las cosas, que se conocen con la razón','Panes con sésamo','Las opiniones de cada uno'],ko:'«¡No, no! Lo del sésamo era broma… creo. Las Ideas son los modelos perfectos y eternos de las cosas, y se conocen con la razón, no con los ojos».'},
 fanLine:()=>{const d=dz();if(d.grad.includes('platon'))return '«¡¿El Maestro te ha dado el título de la Academia?! Yo llevo tres años y aún me pregunta cómo me llamo». Platonákis se seca una lágrima con el manto.';if(d.cur==='platon')return '«¿Tú eres el nuevo discípulo del Maestro? ¿Te ha mirado? ¿Te ha hablado? ¿Qué palabras exactas usó? Espera, que lo apunto».';if(d.cur||d.grad.length)return '«¿Estudias con otro maestro? Bueno… no pasa nada. Todos nos equivocamos. Algunos más que otros».';return '';}};
const FAN_MARCO={id:'marcelo',name:'Marcelo Aurelio',title:'Panadero y estoico entusiasta',glyph:'M',look:{short:true,noHimation:true,chiton:'#e8dfcc',hair:'#5b4532',beard:true},
 cat:'Filosofía',lesson:'El estoicismo, según un panadero',where:'Cerca de Epicteto, al que sigue a todas partes',
 summary:'El estoicismo nació en Atenas hacia el 300 a.C., cuando Zenón de Citio enseñaba en el Pórtico Pintado (la Stoa Poikile). Para los estoicos, el único bien es la virtud; hay que vivir de acuerdo con la razón, que gobierna el universo, y distinguir lo que depende de nosotros de lo que no. En Roma tienen grandes maestros, como Séneca, Musonio Rufo y Epicteto, y más adelante el emperador Marco Aurelio (121-180), que escribirá en griego unas reflexiones para sí mismo, las Meditaciones.',
 intro:'¡Salve! Marcelo Aurelio, estoico y panadero. Primero estoico, luego panadero. Se me ha vuelto a quemar el pan, pero no me afecta: el fuego no depende de mí. Bueno, un poco sí. Pero el disgusto, no.',
 topics:[
  ['¿Quién es Marco Aurelio?','¡Mi ídolo! Un emperador filósofo que, en plena guerra contra los germanos, escribe cada noche pensamientos para sí mismo, en griego. Lo veo en sueños. Es verdad que todavía no ha nacido: nacerá dentro de unos cuarenta años. Pero yo ya soy su fan. Hay que adelantarse. Epicteto dice que me preocupe de lo que depende de mí, y que un emperador que no existe no depende de mí.'],
  ['¿Por qué te llamas así?','Me llamo Marcelo. Lo de Aurelio me lo añadí yo, para parecerme a él. Mi mujer dice que, ya puestos, me cambie el nombre por el del emperador de ahora, Tito, que al menos existe.'],
  ['¿Qué es el estoicismo?','Lo fundó Zenón en Atenas, enseñando en un pórtico pintado, la Stoa: por eso «estoicos». La idea es sencilla: el único bien es la virtud; la salud, el dinero o la fama no son ni buenos ni malos, son indiferentes. Ayer me robaron la capa y respiré hondo, como un sabio. Luego corrí detrás del ladrón. La virtud también hace ejercicio.'],
  ['¿Cómo practicas el estoicismo?','Cada mañana, al levantarme, me preparo: «Hoy me encontraré con gente impaciente, desagradecida y maleducada, y no me enfadaré». Luego abro la panadería y, efectivamente, ahí están todos. Pero no me enfado. Mucho.'],
  ['Dame un consejo estoico','Piensa de vez en cuando que lo que más quieres podría perderse: así lo valorarás más. Yo cada mañana me despido de mi mejor pan como si fuera el último. Luego me lo como, por si acaso.']],
 quiz:{q:'Según los estoicos (y Marcelo Aurelio, cuando no se distrae), ¿cuál es el único bien verdadero?',a:['La virtud','El pan recién hecho','La fama'],ko:'«¡El pan recién hecho es casi un bien! Pero no: para los estoicos, el único bien es la virtud. La salud, el dinero o la fama son indiferentes».'},
 fanLine:()=>{const d=dz();if(d.cur==='epicteto'||d.grad.includes('epicteto'))return '«¡¿Eres discípulo de Epicteto?! ¡Pídele que me deje sentarme en primera fila! Del suelo, claro: no tiene sillas».';if(d.cur==='musonio'||d.grad.includes('musonio'))return '«¡Discípulo de Musonio! Dicen que cuando te corrige, lloras. Yo lloro solo de pensarlo. De emoción».';if(d.cur==='dion'||d.grad.includes('dion'))return '«¿Con Dion de Prusa? ¿Ese que se ríe de los filósofos? Tranquilo: no me enfado. Es una prueba que me manda el destino».';return '';}};
NPCS.push(FAN_PLATON);LESSONS.platonakis={title:FAN_PLATON.lesson,cat:FAN_PLATON.cat,summary:FAN_PLATON.summary,where:FAN_PLATON.where,who:FAN_PLATON.name,fict:true};
ROMA_NPCS.push(FAN_MARCO);
Object.assign(SRC,{platonakis:{a:['Platón, Fedón 74a-75d (lo Igual) y República 596a-597d (la idea de cama)','Diógenes Laercio III 4 (el nombre de Platón)'],m:['G. Vlastos, Platonic Studies (1973)'],n:['Platonákis es inventado y cómico: «-ákis» es un diminutivo del griego moderno, una licencia del juego. El cartel sobre la geometría es una tradición tardía.']}});
ROMA_SRC.marcelo={a:['Diógenes Laercio VII (Zenón y los estoicos)','Epicteto, Manual 1','Marco Aurelio, Meditaciones II 1 (la preparación de cada mañana)','Séneca, Cartas a Lucilio'],m:['P. Hadot, La ciudadela interior (1992)'],n:['Marcelo Aurelio es inventado y cómico. Marco Aurelio nacerá en el 121 y escribirá sus Meditaciones hacia el 170-180: el chiste es que Marcelo dice verlo en sueños.']};

